(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c46"]=[{"id":"00011644","register_sub_id":"101","register_pk":"210660","name":"小原家住宅表門","kana":"おはらけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県館山市南条字五反畑55-3","lat":34.981298,"lng":139.87572611,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.7m、左右袖塀及び西方潜戸付","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"12-0224","desc":"旧長屋門の東にあり、敷地南面を画す。一間薬医門で、両脇に袖塀を付け、西側には潜戸を開く。本柱や冠木は量感があり、梁を四筋架けて桁を受ける。起りを付けた切妻造の屋根には、家紋入の屋根瓦を用いる。往時の景観を今に伝え、表構えに風格を添える表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011644"},{"id":"00011643","register_sub_id":"101","register_pk":"210659","name":"小原家住宅旧長屋門","kana":"おはらけじゅうたくきゅうながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県館山市南条54","lat":34.981302,"lng":139.875579,"geo_status":"db","era":"江戸後期／明治中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0223","desc":"敷地南面に位置する。桁行六・四メートル、梁間三・七メートル、寄棟造。もと長屋門で、門口と西側の居室部分が残る。旧門口には、石敷が残存し、小屋組も二重梁とし重厚な造りであったことを偲ばせる。長屋門の遺構として、敷地景観の変遷を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011643"},{"id":"00011641","register_sub_id":"101","register_pk":"210657","name":"小原家住宅米蔵","kana":"おはらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県館山市南条54","lat":34.98143,"lng":139.87547,"geo_status":"db","era":"弘化2年（1845）頃／平成4年頃増築","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0221","desc":"主屋の南西に東面して建つ。桁行二間半、梁間二間、切妻造桟瓦葺で、正面に下屋庇を付ける。中央北寄りに扉口を設け、北面にのみ一、二階に一所ずつ窓を開く。内部は北面より半間南で通し柱で棟木を受け、登梁を折置に組む。屋敷構えを構成する米蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011641"},{"id":"00011639","register_sub_id":"101","register_pk":"210655","name":"小原家住宅主屋","kana":"おはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県館山市南条54","lat":34.981549,"lng":139.87568,"geo_status":"db","era":"安政6年（1859）頃／明治29年改修、昭和前期増築","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積233㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0219","desc":"館山市中心部東の丘陵地に建つ。主屋は南面し、寄棟造で下屋庇を廻らし玄関を付す主体部の西に、台所部や土間部を接続する。床上は六間取で、奥座敷は床の両端に床脇を設けた豪壮な意匠を見せ、上便所も残る。近世から近代への変遷をよく留める民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011639"},{"id":"00011640","register_sub_id":"101","register_pk":"210656","name":"小原家住宅離れ","kana":"おはらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県館山市南条54","lat":34.981375,"lng":139.875892,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0220","desc":"主屋の南東に西面して建つ。寄棟造に下屋庇を廻らし、入母屋造の玄関を付ける。内部は八畳の座敷と四畳半の茶室からなる。座敷では床脇に円窓を開き、小壁の木口を色漆喰で繰形に仕上げる独自の意匠が見られる良質な離れで、敷地東の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011640"},{"id":"00011642","register_sub_id":"101","register_pk":"210658","name":"小原家住宅文庫蔵","kana":"おはらけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県館山市南条54","lat":34.981567,"lng":139.87549,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0222","desc":"主屋西に東面して建つ。桁行四・五メートル、梁間七・三メートルで正面に下屋を付ける。正面の扉口、妻面の窓とも掛子塗の両開とし、窓庇の持送も漆喰塗とする。内部は板床で壁は横板張とし、二階は棹縁天井を張る。敷地景観を形成する重厚な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011642"},{"id":"00006977","register_sub_id":"101","register_pk":"107959","name":"懐石あた后店舗（旧茂木房五郎家住宅居住棟）","kana":"かいせきあたごてんぽ（きゅうもぎふさごろうけじゅうたくきょじゅうとう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田字愛后裏740-2","lat":35.950848,"lng":139.863663,"geo_status":"db","era":"昭和12／昭和45移築・平成15改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"12 － 0090","desc":"桁行６間半梁間４間で、四周に縁を巡らし、屋根は入母屋造桟瓦葺に銅板葺庇を付ける。内部は部屋を２列各３室に配す。前列奥室が旧主人室で、トコや地袋、平書院などを設ける。縁周囲にはガラス戸を建てる。欄間など細部には繊細な意匠を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006977"},{"id":"00006793","register_sub_id":"101","register_pk":"107775","name":"懐石あた后土蔵（旧茂木房五郎家住宅土蔵）","kana":"かいせきあたごどぞう（きゅうもぎふさごろうけじゅうたくどぞう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田字愛后裏740-2","lat":35.950867,"lng":139.86377,"geo_status":"db","era":"昭和前期／昭和45移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"12 － 0091","desc":"桁行８．４ｍ梁間５．４ｍの切妻造桟瓦葺２階建。外壁は、柱形や窓枠などを表すモルタル塗仕上げとし、基礎のみ洗出し仕上げとする。平側に扉口を設け、銅板張の引戸をたてる。壁上部の鉢巻に掛かる位置には小窓２ヶ所を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006793"},{"id":"00015143","register_sub_id":"101","register_pk":"530567","name":"勝家住宅稲荷社","kana":"かつけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県市川市八幡四丁目1885","lat":35.72518333,"lng":139.93260278,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.2㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0325","desc":"主屋の西側に位置する小社殿。玉石積の基壇上に東面して建つ、一間社流造銅板葺で正面に千鳥破風を飾る。身舎は円柱に桁・梁を架け、束で棟木を支持し、軒は二軒繁垂木。三方に腰組付の縁を廻らし、脇障子を建てる。小規模ながら、精緻なつくりの稲荷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015143"},{"id":"00015142","register_sub_id":"101","register_pk":"530566","name":"勝家住宅主屋","kana":"かつけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県市川市八幡四丁目1885","lat":35.7251,"lng":139.93274167,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0324","desc":"葛飾八幡宮の北東に位置する住宅の主屋。平屋建桟瓦葺の東西棟で、西に玄関と洋間の応接室、中廊下の北に水廻りと内玄関、南に座敷と仏間を配し、南東に離れを突出する。座敷は床廻りに紫檀や赤松など用い、琵琶床と付書院を備え、凝った意匠の近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015142"},{"id":"00003387","register_sub_id":"101","register_pk":"104377","name":"加藤家住宅（茂原牡丹園）主屋","kana":"かとうけじゅうたく（もばらぼたんえん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県茂原市山崎210","lat":35.44059169,"lng":140.26828561,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0049","desc":"桁行７間半，梁間３間半規模，寄棟造，茅葺，平入の農家建築。南面して建ち，西方を土間，東方を上手として四間取状につくり，南面と東面に縁を付ける。丘陵を背にした端整な茅葺屋根が，上総の里山景観を今に伝えており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003387"},{"id":"00003388","register_sub_id":"101","register_pk":"104378","name":"加藤家住宅（茂原牡丹園）長屋門","kana":"かとうけじゅうたく（もばらぼたんえん）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県茂原市山崎210","lat":35.4403681,"lng":140.26840884,"geo_status":"db","era":"天保8","year":1837,"year_source":"db","year_min":1837,"year_max":1837,"year_label":null,"structure":"木造平屋建、茅葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0050","desc":"主屋の南方に建つ。桁行７間半，梁間２間半規模，寄棟造，茅葺の長屋門で，内部は西方がもと隠居部屋，東方を物置とし，外部の腰は簓子下見，上部を白漆喰塗とする。主屋とともに，上総における里山景観を構成する要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003388"},{"id":"00009258","register_sub_id":"101","register_pk":"194051","name":"加藤家住宅主屋","kana":"かとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県富津市笹毛字北舷1","lat":35.2484424,"lng":139.86893951,"geo_status":"db","era":"明治後期／大正前期移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"12 － 0161","desc":"東京湾沿いの集落内に西面して建つ。木造平屋建、建築面積一五九平方メートル、寄棟造桟瓦葺で周囲に下屋を廻らす。正面に切妻破風の玄関を構え、北側に座敷を配し、特に奥座敷では格天井を張るなど上質な室内造作になる。武家住宅風の構えをもつ近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009258"},{"id":"00008097","register_sub_id":"101","register_pk":"132495","name":"加藤家住宅主屋","kana":"かとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市本行徳6-1","lat":35.69114213,"lng":139.91607311,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"12 － 0147","desc":"旧行徳街道に東面して建つ。桁行１２ｍ梁間７．３ｍの木造平屋建、寄棟造桟瓦葺。正面は緩やかに起る切妻屋根の玄関を中央に付け、その両脇は銅板葺の出格子とする。内部は部屋が細分され、銘木を用い、模様ガラス戸を使うなど、上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008097"},{"id":"00008098","register_sub_id":"101","register_pk":"132496","name":"加藤家住宅煉瓦塀","kana":"かとうけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市本行徳6-1","lat":35.69117077,"lng":139.91617832,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、延長34m","structure_material":"煉瓦造","registered":"2010.04.28(平成22.04.28)","register_no":"12 － 0148","desc":"敷地の東辺北寄りと隣地境を矩折れに延びる煉瓦塀で、途中に門を構える。総延長３４ｍ。道路側が高さ２．１ｍ、隣地境の中央が２．１ｍと低く、他は２．８ｍ。煉瓦一枚厚のフランス積で、敷地側に控柱を建て、上部は小屋根状に積む。特徴ある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008098"},{"id":"00001345","register_sub_id":"101","register_pk":"102335","name":"木内家住宅旧蔵","kana":"きうちけじゅうたくきゅうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県香取郡多古町多古2613","lat":35.73790635,"lng":140.4658169,"geo_status":"db","era":"昭和4～6","year":1929,"year_source":"converted","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造2階建、銅板葺、建築面積40㎡","structure_material":"石造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"12 － 0032","desc":"かつて米穀商を営んだ商家で，旧蔵は，敷地奥に建つ住宅と通りに面した店舗に挟まれた位置に建つ。切妻造，銅板葺の旧蔵は，住宅と同じく大谷石積で，開口部と窓枠に稲田石を組む。近代の商家を構成する上で欠かせない倉庫建築として，貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001345"},{"id":"00001344","register_sub_id":"101","register_pk":"102334","name":"木内家住宅主屋","kana":"きうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県香取郡多古町多古2613","lat":35.73782317,"lng":140.46579238,"geo_status":"db","era":"昭和4～6","year":1929,"year_source":"converted","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造2階建、瓦葺、建築面積50㎡","structure_material":"石造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"12 － 0031","desc":"城下町として発展した多古の中心にある商家。かつては米穀商を営み，敷地最奥に住宅が建つ。寄棟造，桟瓦葺，総２階建の住宅は，外壁を大谷石積とするが，階境・軒廻り・開口部等に稲田石を組んで外観に変化を持たせ，当時の意匠の流行をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001344"},{"id":"00001171","register_sub_id":"101","register_pk":"102161","name":"木村家住宅（旧北白川宮邸）","kana":"きむらけじゅうたく（きゅうきたしらかわのみやてい）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県四街道市四街道2-12-44","lat":35.66059187,"lng":140.16354393,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造２階建地下室付，瓦葺，建築面積90㎡","structure_material":"木造２階建地下室付","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0013","desc":"総武本線四街道駅の南西方に位置する。木造２階建、下見板貼りの洋館で、フランス駐在の経験を有する陸軍将校が建設し、一時期北白川宮が住んだと伝える。十字形に交差させた大きな切妻屋根と、サンルームなどを張出した複雑な平面に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001171"},{"id":"00015293","register_sub_id":"101","register_pk":"532417","name":"旧明石家住宅石蔵","kana":"きゅうあかしけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県銚子市新地町1469-56","lat":35.73380278,"lng":140.84220556,"geo_status":"db","era":"明治10年／昭和前期・同45年頃改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"石造2階建、瓦葺、建築面積39㎡","structure_material":"石造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"12 - 0335","desc":"銚子漁港の西方に位置する商家の旧家財蔵。通りに北面する石造二階建寄棟造桟瓦葺で、軒に蛇腹を廻らした丁寧なつくり。二階北面に上下窓を三箇所開け、一連の腕木庇を付す。一階は一室の土間、二階は二室の座敷。洋風意匠を取り入れた明治期の貴重な石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015293"},{"id":"00011648","register_sub_id":"101","register_pk":"210664","name":"旧秋場家住宅主屋","kana":"きゅうあきばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町東浪見字大村1611","lat":35.347079,"lng":140.377856,"geo_status":"db","era":"明治33年／平成25年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積235㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0228","desc":"一宮町南部に位置する。木造平屋一部二階建、寄棟造、桟瓦葺で四周に下屋を廻らし、寄棟造の玄関を付ける。一階は二列各三室を配し西奥の座敷は床の左右に床脇を構える。付書院の欄間に龍、座敷境の欄間に松と鷹が彫刻され、豪壮な細部意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011648"},{"id":"00011649","register_sub_id":"101","register_pk":"210665","name":"旧秋場家住宅土蔵","kana":"きゅうあきばけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県長生郡一宮町東浪見字大村1611","lat":35.346812,"lng":140.378123,"geo_status":"db","era":"天保13年（1842）／平成25年改修","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0229","desc":"長屋門の東で北面する。桁行五間、梁間三間、切妻造妻入で、正面に下屋を付す。内部は一、二階とも一室で、小屋は大径の地棟木に登梁を架ける。外壁は、腰上から一階までを下見板張、二階は漆喰塗とし、母屋・垂木下端まで塗込める形式で丁寧な造りの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011649"},{"id":"00011650","register_sub_id":"101","register_pk":"210666","name":"旧秋場家住宅長屋門","kana":"きゅうあきばけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町東浪見字大村1611","lat":35.346838,"lng":140.377891,"geo_status":"db","era":"明治前期／平成25年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積66㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0230","desc":"敷地南面を画す。桁行九間、梁間三間、寄棟造、茅葺（鉄板仮葺）。中央に門口を開き、両脇に室を設ける。小屋組は、隅木や梁に大きく湾曲したチョウナ梁を用い、端部は持送りにし出桁を受ける構造を持つ。屋敷構えに格式を添える長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011650"},{"id":"00009711","register_sub_id":"101","register_pk":"195540","name":"旧岩崎家末廣別邸東屋","kana":"きゅういわさきけすえひろべっていあずまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県富里市七栄650-25","lat":35.73468083,"lng":140.33828464,"geo_status":"db","era":"昭和初期／平成7改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"12 － 0168","desc":"主屋の南方に位置する。主室と台所からなり、主室周囲に吹放しで軒の深い下屋を廻らす。すべて土間とし、主室では洋風家具を用いる。スギの面皮柱や、天井にコブシの皮付丸太を用い、下屋に曲木の柱や磨き丸太の垂木、蒲天井を用いるなど、数寄屋意匠を加味する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009711"},{"id":"00009712","register_sub_id":"101","register_pk":"195541","name":"旧岩崎家末廣別邸石蔵","kana":"きゅういわさきけすえひろべっていいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県富里市七栄字獅子穴650-25","lat":35.73525484,"lng":140.33782268,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"12 － 0169","desc":"主屋の東方に建ち、桁行三間梁間二間の一室からなる。軸部を木造で組み、その外周に大谷石を積み廻して壁体をつくり、表面をスクラッチタイル貼とし、小屋はキングポストトラスを組む。軒蛇腹まで丁寧にスクラッチタイルを貼り廻す、独特な形式と意匠をもつ蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009712"},{"id":"00009710","register_sub_id":"101","register_pk":"195539","name":"旧岩崎家末廣別邸主屋","kana":"きゅういわさきけすえひろべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県富里市七栄650-25","lat":35.73511152,"lng":140.33764457,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積478㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"12 － 0167","desc":"当地で末廣農場を経営した岩崎久彌の別邸。中庭の西側に玄関を、南側に座敷を並べ、東南に座敷と数寄屋意匠の六畳を張出す。北方には台所や浴室等を並べる。外周のガラス障子の意匠も秀逸で、周囲に廻らした庇とともに、軽快で瀟洒な外観をもつ別邸建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009710"},{"id":"00011654","register_sub_id":"101","register_pk":"210670","name":"旧斎藤家住宅稲荷社","kana":"きゅうさいとうけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町一宮字通町三丁目2987-1","lat":35.375315,"lng":140.362753,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、銅板葺、建築面積0.57㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0234","desc":"敷地北東の主屋背後に南面する一間社流造。組物は二手先詰組とし、間に彫刻を飾る。脇障子、脇羽目板の彫刻のみならず、身舎妻飾に雲の紋様、板支輪にも波の紋様が施される。向拝も木鼻を獅子、中備を龍の彫刻とする。地元の職人による彫刻で随所を飾る稲荷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011654"},{"id":"00011651","register_sub_id":"101","register_pk":"210667","name":"旧斎藤家住宅主屋","kana":"きゅうさいとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町一宮字通町三丁目2987-1他","lat":35.375274,"lng":140.362553,"geo_status":"db","era":"明治30年頃／昭和前期改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0235","desc":"一宮町市街地に位置し、店蔵の背面側に接して建つ。南面に玄関を設け、内縁を介して八畳の茶の間、一〇畳の中の間、一〇畳の奥の間を並べる。奥の間は床・棚を設け、部屋境に板欄間を飾り風格を備える。庭園に向けて開放的外観を見せる近代和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011651"},{"id":"00011645","register_sub_id":"101","register_pk":"210661","name":"旧齋藤家住宅主屋","kana":"きゅうさいとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県松戸市紙敷588","lat":35.773646,"lng":139.937666,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、茅葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0235","desc":"寄棟造、茅葺の南面する住宅で、桁行七間、梁間四間半の規模を有する。床上部は四間取で、西端に式台玄関を設ける。土間上は直材の梁を井桁に組み、天井を張る。近世以来の農家に、近代的な要素が加わった住宅建築で、近代初頭の地域の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011645"},{"id":"00011653","register_sub_id":"101","register_pk":"210669","name":"旧斎藤家住宅土蔵","kana":"きゅうさいとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町一宮字通町三丁目2987-1","lat":35.375305,"lng":140.362816,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0233","desc":"敷地北東角に建つ。桁行三間、梁間三間、切妻造妻入で、正面に一間半の庇が付く。一、二階とも一室で、小屋は和小屋とし、三重梁を架ける堅牢な造り。一階の扉口、二階両妻の窓廻りの漆喰塗も丁寧に仕上げ、屋敷地の構成要素となる土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011653"},{"id":"00011652","register_sub_id":"101","register_pk":"210668","name":"旧斎藤家住宅店蔵","kana":"きゅうさいとうけじゅうたくみせぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町一宮字通町三丁目2987-1他","lat":35.375242,"lng":140.362435,"geo_status":"db","era":"明治中期／平成26年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0232","desc":"通りに西面して建つ。桁行八・五メートル、梁間七・一メートルの土蔵造二階建、切妻造平入で、正面に奥行一間の下屋が付く。一階は下屋と南西寄りを土間とし、他は板敷で、二階には良質な座敷を備える。正面は三連窓や軒蛇腹を塗込めた重厚な外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011652"},{"id":"00015144","register_sub_id":"101","register_pk":"530568","name":"旧下総御料牧場（三里塚記念公園）貴賓館","kana":"きゅうしもふさごりょうぼくじょう（さんりづかきねんこうえん）きひんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県成田市三里塚御料1-34","lat":35.74892778,"lng":140.37253889,"geo_status":"db","era":"明治9年／明治21年移築、大正8年増築","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積279㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0326","desc":"旧下総御料牧場の迎賓施設。南面して建つ平屋建寄棟造茅葺で、南面西寄りに玄関、北東に風呂便所棟を突出する。内部は中廊下の南に和室を並べ、北に洋間のホールを配す。北面は上下窓を開け、外壁下見板張に屋根茅葺とする独特な外観。御料牧場の貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015144"},{"id":"00015145","register_sub_id":"101","register_pk":"530569","name":"旧下総御料牧場（三里塚記念公園）防空壕","kana":"きゅうしもふさごりょうぼくじょう（さんりづかきねんこうえん）ぼうくうごう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県成田市三里塚御料1-34","lat":35.74926111,"lng":140.37255833,"geo_status":"db","era":"昭和16年／平成22年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造地階、面積69㎡、上部盛土付","structure_material":"鉄筋コンクリート造地階","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0327","desc":"旧下総御料牧場内の皇太子殿下用と伝わる防空壕。マウンド状盛土下に鉄筋コンクリート造、壁厚７０センチメートルの主室を配し、東西に通路を付したＨ字形平面。主室前室と通路境を分厚い鉄扉で遮蔽。当時の技術を駆使し戦時下の緊張を伝える堅固な防空施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015145"},{"id":"00011073","register_sub_id":"101","register_pk":"205180","name":"旧武居家住宅主屋","kana":"きゅうたけいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県佐倉市宮小路町60","lat":35.716675,"lng":140.224394,"geo_status":"db","era":"江戸後期／平成9移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0187","desc":"佐倉藩士の住宅。接客と生活空間を二列に分けた平面が特徴的。木柄の細い柱を一間毎に立てる古式を見せ、それぞれの列に入口を設けて武家住宅の特色をよく示す。表向の割合が小さく、座敷には長押を付けないなど、比較的小規模な武家住宅の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011073"},{"id":"00011077","register_sub_id":"101","register_pk":"205184","name":"旧藤谷家住宅主屋","kana":"きゅうとうやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県袖ケ浦市代宿字陣場303-3他","lat":35.456319,"lng":140.027723,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積116㎡","structure_material":"木造平屋一部2階建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0191","desc":"東面して建つ寄棟造桟瓦葺で、八畳間三室を一列に並べ、その背面側に板敷の部屋を設ける。南端間には座敷飾を備える。玄関脇八畳の上部には二階を設け、朱色を大胆に散らした繊維壁とする。細部まで意匠を凝らし、伝統技法を用いた昭和中期上総の民家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011077"},{"id":"00011078","register_sub_id":"101","register_pk":"205185","name":"旧藤谷家住宅離れ","kana":"きゅうとうやけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県袖ケ浦市代宿字陣場303-3他","lat":35.456168,"lng":140.027675,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0192","desc":"主屋の南方に東面して建つ。八畳間と六畳間を南北に並べ、東に玄関を突出させる。六畳間背面には板間を付設し、北に勝手口を開く。八畳間は座敷飾を備え、自然木も用いて卍型に格天井を張るなど、野趣に溢れた造形を見せる。屋敷構えを形成する建物となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011078"},{"id":"00002607","register_sub_id":"101","register_pk":"103597","name":"旧水田家住宅主屋","kana":"きゅうみずたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県鴨川市西339","lat":35.09923277,"lng":140.00305596,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0042","desc":"愛宕山の麓，曽呂川流域の西奥部に位置する。桁行８間半，梁間５間規模の寄棟造，もと茅葺農家で，東側を土間とし，床上はイロリを切った１５畳のザシキを中心に食違いの５室構成とする。西面に縁側，南面には瓦葺の下屋を差掛けるなど房総民家の特色をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002607"},{"id":"00012703","register_sub_id":"101","register_pk":"367606","name":"旧森田家住宅主屋","kana":"きゅうもりたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県館山市北条2321","lat":34.99779972,"lng":139.86096,"geo_status":"db","era":"昭和8年頃／昭和10年頃改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 281","desc":"館山駅西側の住宅地にある旧国鉄機関区長宅。北正面の木造平屋建、寄棟造桟瓦葺で正背面に下屋を付し、正面東寄りに入母屋造の玄関を出す。内部は東に客座敷を設け、中廊下を通して西に居室4室を配する。駅前に開けた近代住宅地の様相を伝える和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012703"},{"id":"00016652","register_sub_id":"101","register_pk":"579136","name":"小坂家住宅主屋","kana":"こさかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県印旛郡酒々井町上岩橋1535","lat":35.73554,"lng":140.281656,"geo_status":"db","era":"江戸末期／昭和48年改修、令和7年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建物面積201㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"12 - 0344","desc":"市街地北東の台地上に建つ庄屋の主屋。南面して建つ寄棟造平入茅葺（鉄板仮葺）、桁行約一九メートルの大型民家で、西の土間脇に一五畳を配す。東は式台から次の間、中の間、奥の間を並べ、東面に縁を付す。広大な土間上に現す小屋組が豪壮な上層農家の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016652"},{"id":"00011638","register_sub_id":"101","register_pk":"210654","name":"後藤家住宅稲荷社","kana":"ごとうけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県市川市新田一丁目296-1","lat":35.726772,"lng":139.916948,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積0.32㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0218","desc":"千葉街道から主屋に至る路地沿いに祀られる稲荷社。一間社流造、銅板葺。大谷石積の基壇の上に建ち、土台上に立つ柱には几帳面を施し、正面格子戸両開、側背面は板壁とする。装飾を抑えた素朴な造形で、昭和戦前期の地域の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011638"},{"id":"00011637","register_sub_id":"101","register_pk":"210653","name":"後藤家住宅主屋","kana":"ごとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県市川市新田一丁目296","lat":35.726467,"lng":139.916747,"geo_status":"db","era":"大正15年／平成24年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び銅板葺、建築面積149㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0217","desc":"玄関右手に洋風応接室を設け、左手に茶の間・寝室など私的空間を配する。南棟の座敷は銘木を用いた本格的な座敷飾を備える。中廊下を設けると共に、南・東面の縁ではガラス戸を用いて開放性を高めるなど、様式美に加え機能性を備えた良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011637"},{"id":"00004336","register_sub_id":"101","register_pk":"105326","name":"近藤家住宅主屋","kana":"こんどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県四街道市下志津新田2530-4","lat":35.66173673,"lng":140.15384779,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"12 － 0059","desc":"新田中央道路に東面する敷地中央西寄りに南北棟で建つ。寄棟造，桟瓦葺の木造平屋建で，東面と南面に下屋を廻し，東面中央南寄りに緩く起りを付けた切妻造玄関を突出させる。明治３０年代の陸軍演習地拡張に関連して当新田南端地区へ移転新築した農家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004336"},{"id":"00004337","register_sub_id":"101","register_pk":"105327","name":"近藤家住宅土蔵","kana":"こんどうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県四街道市下志津新田2530-4","lat":35.66155366,"lng":140.15411472,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"12 － 0060","desc":"主屋の東南方に南北棟で建つ。桁行３間梁間２間，置屋根式の切妻造，桟瓦葺の平入２階建土蔵で，西面に土間庇を差し掛けて戸口を開ける。外部は腰を押縁下見板張，上部を白漆喰塗とし，戸口や２階南北両妻面の窓は額縁に引き分けの土戸を入れた丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004337"},{"id":"00004338","register_sub_id":"101","register_pk":"105328","name":"近藤家住宅長屋門","kana":"こんどうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県四街道市下志津新田2530-4","lat":35.66164486,"lng":140.15423052,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"12 － 0061","desc":"主屋の東方，道路から退いた位置に南北棟で建つ。桁行９間梁間２間半規模，寄棟造，桟瓦葺の木造平屋建で，中央に門口を開き，北側と南側に物置などを配する。たちの高い姿形に特徴があり，上棟破魔矢の墨書から「大工山川伊三郎作」が確認される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004338"},{"id":"00006523","register_sub_id":"101","register_pk":"107506","name":"山静堂主屋","kana":"さんせいどうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県富津市関尻字堂前483","lat":35.21591314,"lng":139.92596802,"geo_status":"db","era":"昭和3／昭和6増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積300㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0082","desc":"南北棟の入母屋造，平屋建，妻入で，正面に切妻造玄関を設けた大規模住宅。北奥に座敷，東に台所等を配し，西には下見板張の診療所が渡廊下で繋がる。良材を多用した上質で丁寧なつくりで，妻飾りに設けられた洋風の丸窓など，当時の意匠の嗜好を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006523"},{"id":"00010564","register_sub_id":"101","register_pk":"201138","name":"塩田家住宅主屋","kana":"しおだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町小土呂字東中野197-1","lat":35.30898592,"lng":140.24049125,"geo_status":"db","era":"明治34年／平成元年頃改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋一部2階建、茅葺、建築面積203㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"12－0185","desc":"ほぼ東を正面として建ち、桁行九間梁間五間半で寄棟造茅葺とし、四面に幅一間の下屋を廻らし、正面に切妻造桟瓦葺の玄関を持つ。一階は変形六間取平面で北半に二階を設ける。たちの高い軸部や深い出桁造の軒廻りなど、当地域の近代民家の指標となる存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010564"},{"id":"00013957","register_sub_id":"101","register_pk":"508217","name":"式場隆三郎家住宅","kana":"しきばりゅうざぶろうけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県市川市国府台六丁目2412","lat":35.75574444,"lng":139.90311667,"geo_status":"db","era":"昭和14年／同58年頃改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0310","desc":"二階建切妻造桟瓦葺の主体部東西に平屋を接続。妻壁は貫と束を密に配する。内部は玄関から矩折に居間、応接間、書斎が展開。設計柳宗悦、濱田庄司、現場監理河井寬次郎で、洋風暖炉に朝鮮風板敷・建具等、東西の様式が融合する民藝の意匠が色濃く顕れた住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013957"},{"id":"00001245","register_sub_id":"101","register_pk":"102235","name":"渋谷嘉助旧宅正門","kana":"しぶやかすけきゅうたくせいもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県香取郡多古町北中83","lat":35.745205,"lng":140.495834,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造平屋建，瓦葺，建築面積99㎡","structure_material":"煉瓦造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0026","desc":"民家では異例の煉瓦造門。正面左右を倉とする長屋門風の形態をとる。イギリス積で、バットレスにより正面を３間に区切り、中央間に煉瓦小口３枚厚、半楕円形アーチの出入口を設ける。側面上部２連の丸窓も特徴的。施主の進取な気概を感じ取ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001245"},{"id":"00013350","register_sub_id":"101","register_pk":"368438","name":"澁谷家住宅主屋","kana":"しぶやけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県鎌ケ谷市中佐津間一丁目77","lat":35.79693889,"lng":140.00329167,"geo_status":"db","era":"文政9年（1826）／昭和53年改修、同61年増築","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積186㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0300","desc":"敷地中央に東面して建つ、寄棟造茅葺（金属板仮葺）で、三面を出桁造とし正面南端に式台玄関を付し屋根を葺下ろす。前後二列に部屋を並べ北側を土間とし、床上部は正面中央にザシキ、その南にナカノマとオクを配す。地域の旧家にふさわしい雄大な規模の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013350"},{"id":"00013351","register_sub_id":"101","register_pk":"368439","name":"澁谷家住宅米蔵","kana":"しぶやけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県鎌ケ谷市中佐津間一丁目77","lat":35.79673889,"lng":140.00347222,"geo_status":"db","era":"嘉永元年（1848）／昭和50年代改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0301","desc":"主屋南東に西面して建つ。土蔵造二階建、桁行三間、梁間二間、切妻造桟瓦葺。外壁は漆喰塗で、二階窓まで下見板張とし、二階の南妻面と背面に庇付の窓を付す。内部は竪板張とし、小屋は登り梁形式である。北東の門とともに、旧家の屋敷構えを引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013351"},{"id":"00013352","register_sub_id":"101","register_pk":"368440","name":"澁谷家住宅門","kana":"しぶやけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県鎌ケ谷市中佐津間一丁目77","lat":35.7968,"lng":140.00359722,"geo_status":"db","era":"昭和前期／昭和50年代改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.9m、袖塀付","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0302","desc":"主屋の正面に東面して建ち、前面には道路まで畑が広がる。切妻造桟瓦葺の一間薬医門で、本柱に冠木を渡し、女梁男梁を重ね、束を立て棟木を受ける。門の南北には桟瓦葺、簓子下見板張の塀が接続し、屋敷地の東方に広がる畑とともに、集落景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013352"},{"id":"00008417","register_sub_id":"101","register_pk":"134813","name":"昭和学院創立記念館","kana":"しょうわがくいんそうりつきねんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県市川市東菅野2-1470-1他","lat":35.73469484,"lng":139.93119565,"geo_status":"db","era":"昭和6年／昭和18年・昭和31年移築・昭和43年・昭和55年改修・平成21年移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積112㎡","structure_material":"木造平屋一部2階建","registered":"2011.01.26(平成23.01.26)","register_no":"12 － 0150","desc":"学院敷地の北寄りに位置する。南北棟の入母屋造で建ちの高い二階屋と、東面玄関を入母屋造、西面を寄棟造とする平屋がＬ字に並ぶ独特の外観をつくる。ともに桟瓦葺、建築面積一一二平方メートル。玄関脇に洋間を置き、丁寧なつくりの座敷が並ぶ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008417"},{"id":"00003844","register_sub_id":"101","register_pk":"104834","name":"翠州亭（旧スイス大使館）","kana":"すいすてい（きゅうすいすたいしかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県長生郡長柄町上野527-2","lat":35.477806,"lng":140.24324,"geo_status":"db","era":"昭和5／昭和54移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積741㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"12 － 0056","desc":"実業家の別邸として約１年半の工期で建設された和風の邸宅。南面する入母屋造，総２階建を中心に，西側にＬ字型の平屋建を連ね，南東部にも平屋建を接続する。京間で設計され，檜などの良材をふんだんに用いた上質の数寄屋風で，随所に繊細な造形がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003844"},{"id":"00007976","register_sub_id":"101","register_pk":"128808","name":"鈴木家住宅石垣","kana":"すずきけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県富津市金谷字上原2288-1他","lat":35.1686272,"lng":139.82012983,"geo_status":"db","era":"大正前期／大正12頃・昭和28改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造、延長55m","structure_material":"石造","registered":"2010.01.15(平成22.01.15)","register_no":"12-0145","desc":"屋敷地の南正面、旧本道沿いに、門を挟んで東側３０ｍ、西側２５ｍを測る。縦０．３ｍ長さ０．８ｍの房州石の切石を６～７段、高さ１．８ｍに積む。横目地が通る整層積。門付近では厚さ１．７ｍで、両端部では薄くする。長大な石垣が独特の街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007976"},{"id":"00002611","register_sub_id":"101","register_pk":"103601","name":"鈴木家住宅石蔵","kana":"すずきけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県鴨川市西町1139-3","lat":35.11636464,"lng":140.11439748,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積13㎡","structure_material":"石造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0046","desc":"離れ縁側の西突き当たりに建つ。桁行２間半，梁間２間規模，平屋建の蔵で，東西棟，桟瓦葺，切妻造，妻入とする。外部は塗込められて土蔵のように見えるが，構造は大谷石造である。棟梁は離れと同じ地元の大工石井政吉で，関東大震災を挟んでの建設と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002611"},{"id":"00007973","register_sub_id":"101","register_pk":"128805","name":"鈴木家住宅石蔵","kana":"すずきけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県富津市金谷字上原2288-1他","lat":35.16901198,"lng":139.81990495,"geo_status":"db","era":"明治35／大正12・昭和54改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造2階建、瓦葺、建築面積49㎡","structure_material":"石造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12-0142","desc":"主屋の西北に位置する。東西棟の桁行４．９ｍ梁間７．６ｍ２階建、寄棟造妻入桟瓦葺の石蔵で、東面に平屋建を取り付ける。主棟の棟積や鬼瓦は大振りで、重厚感をもつ。房州石の中でも最上級とされる桜目の石を丁寧に積み上げた石蔵で、成熟した石造の技法を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007973"},{"id":"00007975","register_sub_id":"101","register_pk":"128807","name":"鈴木家住宅井戸","kana":"すずきけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県富津市金谷字上原2288-1他","lat":35.16906933,"lng":139.8198807,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造、面積1.5㎡","structure_material":"石造","registered":"2010.01.15(平成22.01.15)","register_no":"12-0144","desc":"敷地の北寄り、石蔵の北側に位置する。井戸枠は方１．２ｍ厚さ０．６１ｍの一枚石を０．８７ｍ径に刳り貫いたもので、四隅に面取を施す。その下部は延石を円形に積み上げ、さらに岩盤を掘り下げ、深さ８．２ｍを測る。房州石を多く使い、産地の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007975"},{"id":"00007974","register_sub_id":"101","register_pk":"128806","name":"鈴木家住宅稲荷社","kana":"すずきけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"千葉県","address":"千葉県富津市金谷字上原2288-1他","lat":35.1690201,"lng":139.82034055,"geo_status":"db","era":"昭和28／昭和50改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"石造、面積0.7㎡","structure_material":"石造","registered":"2010.01.15(平成22.01.15)","register_no":"12-0143","desc":"主屋の北東、庭池のほとりに西面して建つ石造の稲荷社。石積基壇の上に、さらに基礎石を置き、間口０．２２ｍ高さ０．５９ｍの切妻造、正面千鳥破風付の一間社社殿を載せる。柱や長押、垂木、妻飾、扉などを削り出しており、高度な技術が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007974"},{"id":"00006099","register_sub_id":"101","register_pk":"107084","name":"鈴木家住宅表門","kana":"すずきけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県館山市沼1619","lat":34.98215089,"lng":139.84625254,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"石造、間口2.8m、左右袖塀及び柱付","structure_material":"石造","registered":"2007.05.15(平成19.05.15)","register_no":"12 － 0069","desc":"主屋の前方に位置し，前面道路境に北面して立つ。玉石練積で，高さ３．２ｍ，間口２．８ｍとし，角状の柱が一対立ち，両側に袖塀を円弧状に前方へ延ばし柱を立てる。鉄扉を失うが，吊り金具が現在も残る。主屋及び前庭に相応しい重厚なつくりで，表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006099"},{"id":"00006220","register_sub_id":"101","register_pk":"107204","name":"鈴木家住宅蔵","kana":"すずきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県館山市沼1619","lat":34.981766,"lng":139.846497,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"12 － 0068","desc":"主屋東方に建つ内蔵。桁行３間，梁間２間，切妻造，桟瓦葺の木造２階建で，蔵前によって主屋と繋ぐ。南面１・２階共に塗戸を吊り込み，庇を付ける。外壁及び鉢巻は目地を切った石造風のモルタル洗出しとし，主屋東側も同じ仕上げで，統一感を持った外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006220"},{"id":"00006218","register_sub_id":"101","register_pk":"107202","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県館山市沼1619","lat":34.981804,"lng":139.846283,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階一部平屋建、スレート葺及び鉄板葺、建築面積285㎡","structure_material":"木造2階一部平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"12 － 0067","desc":"館山港を眺望する位置に建つ。全体が和洋折衷様式の木造２階一部平屋建とする。正面外観は中央のペディメント付ポーチや両翼の半切妻屋根，円弧状の持送り等，洋風意匠とする。内部は床のコルクタイルや壁紙等の内装がよく残り，座敷床の間等の造作も良質。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006218"},{"id":"00002609","register_sub_id":"101","register_pk":"103599","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県鴨川市西町1139-3","lat":35.11644,"lng":140.114594,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、茅葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0044","desc":"東条海岸と平行する旧道から奥まった敷地に建つ。桁行７間，梁間５間規模，茅葺，寄棟造，平入の農家で，棟近くに煙出しを開け，南面に瓦葺の下屋を出す。東側を土間，床上を５室構成とし，西南に式台玄関と西面に縁側を設けるなど房総民家の特色をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002609"},{"id":"00007972","register_sub_id":"101","register_pk":"134287","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県富津市金谷字上原2288-1他","lat":35.16892188,"lng":139.82001646,"geo_status":"db","era":"昭和28／昭和60改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"12-0141","desc":"旧金谷村の本道に面する敷地の中央に南面して建つ。東西１７ｍ南北１１ｍの木造平屋建。寄棟造の主棟に落棟を付ける複雑な桟瓦葺屋根を造り、下屋をまわす。基礎や風呂場などに地元産房州石を使い、洋間天井の鏝細工のアカンサスなど見応えがある細部をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007972"},{"id":"00002610","register_sub_id":"101","register_pk":"103600","name":"鈴木家住宅離れ","kana":"すずきけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県鴨川市西町1139-3","lat":35.116417,"lng":140.114456,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0045","desc":"東南隅で主屋西北隅部に接続する。桁行５間，梁間３間規模の東西棟，桟瓦葺，寄棟造で，内部は西側に床の間をもつ１０畳と８畳の２室構成とし，東面に便所等，東北方に風呂場を配する。南面は全面を縁側とし，その前面に土庇を設けるなど開放的な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002610"},{"id":"00005766","register_sub_id":"101","register_pk":"106754","name":"須藤家住宅主屋","kana":"すどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県南房総市千倉町大貫543","lat":34.97530463,"lng":139.92251333,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、茅葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"12 － 0066","desc":"敷地の奥寄りに南面して位置し，桁行５間，梁間４間半で，木造平屋建，寄棟造，茅葺とする。内部は広間型三間取平面で，西側には８畳の客間と６畳の座敷を南北に配する。軒四方をせがい造として，正面下屋は桟瓦葺屋根とする。茅屋根の曲線をきれいに整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005766"},{"id":"00001167","register_sub_id":"101","register_pk":"102157","name":"西洋館倶楽部（渡辺家住宅）","kana":"せいようかんくらぶ（わたなべけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県市川市新田5-6-21","lat":35.729961,"lng":139.911942,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造３階建，スレート葺，建築面積146㎡","structure_material":"木造３階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0009","desc":"京成本線の市川真間駅の南方、住宅地の一画に建つ。東京の実業家のゲストハウスとして建てられた洋館で、玄関ホール部のベイウインドウ状の張出しと南西北３面の袴腰型切妻破風を中核とする屋根構成に特徴がある。コンサートホール等として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001167"},{"id":"00012709","register_sub_id":"101","register_pk":"367612","name":"染谷家住宅井戸屋形","kana":"そめやけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造、銅板葺、面積12㎡","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0287","desc":"前蔵の北側に建つ。東西棟の切妻造銅板葺、桁行が広い方一間吹放ち形式で、中央東寄りに煉瓦造、白タイル張の円筒形井戸枠を置く。軸部は角柱を内転びに立て、内法貫と桁で軸部を固める。良材を用いた大型の井戸屋形で、生活空間の構成に欠かせない附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012709"},{"id":"00012710","register_sub_id":"101","register_pk":"367613","name":"染谷家住宅稲荷社","kana":"そめやけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺，建築面積3.1㎡、覆屋付","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0288","desc":"敷地西北隅の高台に東面して建つ屋敷神を祀る小社。切妻造桟瓦葺の覆屋内にある三間社流造板葺で、庇の中柱二本を省略し、正側面に切目縁を廻す。身舎に組物を用いず、向拝は三斗実肘木、中備は蟇股とする。上層農家の伝統的な屋敷構えを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012710"},{"id":"00012704","register_sub_id":"101","register_pk":"367607","name":"染谷家住宅主屋","kana":"そめやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"弘化4年（1847）","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積344㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0282","desc":"手賀沼南岸の高台にある名主宅。主屋は敷地中央に東面して建つ。寄棟造桟瓦葺で正面北端に曲屋状に土間を突出し、南端に式台を設ける。内部は表中央部の一八畳を中心に室を配し、南奧を座敷とする。県西部屈指の大型民家で、江戸末期の民家形式の指標になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012704"},{"id":"00012711","register_sub_id":"101","register_pk":"367614","name":"染谷家住宅長屋門","kana":"そめやけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"江戸末期／昭和50年代改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0289","desc":"敷地南辺の中央部に南面して建つ。寄棟造銅板葺の平屋建、四周出桁造の一軒とし、中央に門口、東西に各一室を設ける。門口は五平の柱に成の高い差物を渡して両開き板扉を備える。外壁は真壁造の漆喰塗、腰下見板張。上層農家の格式ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012711"},{"id":"00012708","register_sub_id":"101","register_pk":"367611","name":"染谷家住宅肥料小屋","kana":"そめやけじゅうたくひりょうごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0286","desc":"敷地北端に南面して建つ。木造平屋建、切妻造鉄板葺で、外壁は真壁造の中塗仕上、腰横板張で、正面東寄りに戸口を設ける。内部は土間で、東西二室に間仕切り、肥料の生成と貯蔵に用いた。簡明なつくりだが、伝統的な農家の生活の様相を伝える構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012708"},{"id":"00012705","register_sub_id":"101","register_pk":"367608","name":"染谷家住宅風呂場","kana":"そめやけじゅうたくふろば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0283","desc":"主屋土間部の北側に南面して建つ。寄棟造セメント瓦葺で、棟中央に切妻屋根の気抜を設ける。内部は中央を浴室とし、東に脱衣室、西に焚口と便所を配する。脱衣室は東面に出窓を設け、北面に造付の長椅子を設ける。大正期の旧家の暮らしぶりを伝える附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012705"},{"id":"00012707","register_sub_id":"101","register_pk":"367610","name":"染谷家住宅文庫蔵","kana":"そめやけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"慶應3年（1867）","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0285","desc":"主屋の後方に東面して建つ。土蔵造二階建、切妻造桟瓦葺で、正面に下屋を付し、中央に扉口を設ける。外壁は漆喰塗で鉢巻二段を廻し、開口部の観音扉など重厚に仕上げる。内部は上下階とも板敷、小屋組は登梁である。上層農家の屋敷構えに欠かせない附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012707"},{"id":"00012706","register_sub_id":"101","register_pk":"367609","name":"染谷家住宅前蔵","kana":"そめやけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県柏市鷲野谷字稲荷内24","lat":35.84808583,"lng":140.03948194,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"12 － 0284","desc":"主屋の前方に西面して建つ。もと米蔵と伝わる。切妻造桟瓦葺の二階建で、正面に下屋を通し、南寄りに戸口を設ける。外壁は真壁造の漆喰塗、腰海鼠壁で、二階東面中央に窓を穿つ。内部は上下階とも板敷で和小屋を組む。県西部の農家の伝統的な構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012706"},{"id":"00011647","register_sub_id":"101","register_pk":"210663","name":"高原家住宅店蔵","kana":"たかはらけじゅうたくみせぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町一宮字櫻馬場3030","lat":35.375773,"lng":140.361233,"geo_status":"db","era":"明治後期／平成26年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0227","desc":"玉前神社参道沿いに建つ。桁行六・三メートル、梁間八・二メートル、土蔵造二階建、切妻造平入で、正面に奥行一間の下屋が付く。一階は一室で、下屋境の柱は太く、揚戸痕跡が残る。二階の三連窓や重厚な持送りなどで正面を飾り、門前の景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011647"},{"id":"00016651","register_sub_id":"101","register_pk":"579135","name":"立﨑家住宅主屋","kana":"たつざきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県佐倉市木野子字屋敷256-1他","lat":35.68442,"lng":140.234599,"geo_status":"db","era":"明治後期／昭和前期・同30年代・平成4年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"12 - 0343","desc":"市街南部に位置する農家の主屋。敷地中央に東面して建つ寄棟造桟瓦葺で北は土間、南は前後二列に部屋を並べ、南・東面に縁を廻らし下屋を付す。中央の１２畳に仏壇と神棚を設け、南西に床、床脇、付書院を構えた座敷とする。材料吟味した近代の大規模な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016651"},{"id":"00000124","register_sub_id":"101","register_pk":"101114","name":"千葉市民ギャラリー・いなげ（旧神谷伝兵衛稲毛別荘）","kana":"ちばしみんぎゃらりー・いなげ（きゅうかみやでんべえいなげべっそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県千葉市稲毛区稲毛1-8-35","lat":35.63422443,"lng":140.08319785,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"鉄筋コンクリート2階建，瓦葺，建築面積113㎡","structure_material":"鉄筋コンクリート2階建","registered":"1997.05.07(平成9.05.07)","register_no":"12 － 0001","desc":"本格的なフランスワインの醸成技術を導入したことで知られる初代神谷伝兵衛の別荘で，１階正面にはロマネスク風の５連アーチが並び吹き放しの柱廊を配し，２階は非対称として変化のある洒落た外観構成になる。市民ギャラリーとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000124"},{"id":"00002133","register_sub_id":"101","register_pk":"103123","name":"東葉高等学校正門（旧近藤家住宅長屋門）","kana":"とうようこうとうがっこうせいもん（きゅうこんどうけじゅうたくながやもん）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県船橋市飯山満町2-670-1","lat":35.71146826,"lng":140.02137428,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"12 － 0037","desc":"東北にゆるぎ地蔵を望む丘の裾際に位置する旧家の長屋門。桁行１１間２尺，梁行２間半と比較的規模が大きく，腰を簓子下見，上部を白漆喰塗とし，正面と背面を出桁造として桟瓦葺の寄棟屋根を載せる。高校の正門及び部室として生徒たちに親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002133"},{"id":"00011635","register_sub_id":"101","register_pk":"210651","name":"滑川家住宅主屋","kana":"なめかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県銚子市野尻町27-1","lat":35.768373,"lng":140.756664,"geo_status":"db","era":"明治6年頃","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積305㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0215","desc":"利根川下流域の河岸集落に建つ。主屋は、土間・茶の間などの主体部、帳場をもつ玄関部、二間続きの座敷部からなる。座敷は、葡萄と栗鼠、仙人、梅が描かれた杉戸や襖を建て込み、格調高い室内意匠を見せる。河岸問屋としての営為を今に伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011635"},{"id":"00011636","register_sub_id":"101","register_pk":"210652","name":"滑川家住宅長屋門","kana":"なめかわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県銚子市野尻町27-1","lat":35.768187,"lng":140.756707,"geo_status":"db","era":"江戸末期／昭和15年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"12-0216","desc":"旧銚子街道沿いに南面して建つ。桁行八間半、梁間三間、寄棟造桟瓦葺で、軒をせがい造とし疎垂木を配る。中央間を門口とし、板戸を吊り両脇に潜戸を開く。左右は一室で、東側は土間床とする。建ちの高い長屋門で、重厚な表構えを形成し、街道の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011636"},{"id":"00013961","register_sub_id":"101","register_pk":"508221","name":"根本家住宅主屋","kana":"ねもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県我孫子市都部字宿通93-1","lat":35.86985833,"lng":140.06636667,"geo_status":"db","era":"江戸末期／明治34年、昭和50年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積226㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0314","desc":"利根川と手賀沼に挟まれた台地に位置し東面する。木造平屋建、寄棟造桟瓦葺。内部の北は土間、南は床上部で南列に三間続きの座敷を並べて前面に式台玄関を付す。その北は広間及び八畳で、さらに二室を土間に張出す。千葉の上層農家の形式を遺す大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013961"},{"id":"00013962","register_sub_id":"101","register_pk":"508222","name":"根本家住宅北倉","kana":"ねもとけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県我孫子市都部字宿通93-1","lat":35.8698,"lng":140.06666111,"geo_status":"db","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0315","desc":"北側通りから敷地東辺に延ばすアプローチを西に折れた敷地入口の北側の倉庫。木造二階建、切妻造桟瓦葺、外壁は真壁造漆喰塗仕上で腰は下見板張。南に窓を設け西に下屋を付し戸口とする。内部は各階とも一室で二階は独立柱が立つ。屋敷景観の一画をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013962"},{"id":"00013963","register_sub_id":"101","register_pk":"508223","name":"根本家住宅南倉","kana":"ねもとけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県我孫子市都部字宿通93-1","lat":35.86965,"lng":140.06661667,"geo_status":"db","era":"慶応3年(1867)","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0316","desc":"北側通りから敷地東辺に延ばすアプローチを西に折れた敷地入口の南側の倉庫。木造二階建、切妻造桟瓦葺、外壁は真壁造漆喰塗仕上、腰は下見板張、南に窓を設ける。西に下屋を付し戸口を設け南側を室に区画する。内部は各階とも一室。屋敷の一画を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013963"},{"id":"00013964","register_sub_id":"101","register_pk":"508224","name":"根本家住宅屋敷社","kana":"ねもとけじゅうたくやしきしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県我孫子市都部字宿通93-1","lat":35.86976667,"lng":140.06628889,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積0.6㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0317","desc":"敷地南西、主屋の南に位置。一間社流造銅板葺。玉石積基壇の上に土台を廻し柱を立て切目長押、内法長押で固める。木階五級を付し正面に両開き板戸を吊る。棟積が高く巴紋を三箇所付し、鬼板も大振り。小規模だが造りの丁寧な屋敷社で奥庭の景観を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013964"},{"id":"00000125","register_sub_id":"101","register_pk":"101115","name":"野田市市民会館（旧茂木佐平治家住宅）主屋","kana":"のだししみんかいかん（きゅうもぎさへいじけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田370-8","lat":35.94575492,"lng":139.86556429,"geo_status":"db","era":"大正11～13頃","year":1922,"year_source":"converted","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積618㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"12 － 0002","desc":"醤油醸造で名の知られた茂木佐平治の旧宅で，純和風の建築。平面は，西面に入母屋屋根の車寄せが付く玄関部，広間を中心にした接客部及び奥側の居室部から構成される。大正期の和風住宅の好例であり，現在市民会館として広く使われ親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000125"},{"id":"00000126","register_sub_id":"101","register_pk":"101116","name":"野田市市民会館（旧茂木佐平治家住宅）茶室","kana":"のだししみんかいかん（きゅうもぎさへいじけじゅうたく）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田370-8","lat":35.94582368,"lng":139.86596112,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建，柿葺，建築面積28㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"12 － 0003","desc":"主屋の東側に建つこけら葺の茶室で，簡素な造りながら吟味された材料を用いた内部の造作は技術的に高度で見るべきものがある。松樹庵とも呼ばれ，南側に腰掛待合や蹲・灯籠が一体的に残り往時の面影をよく残す。茶会等に広く活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000126"},{"id":"00003390","register_sub_id":"101","register_pk":"104380","name":"廣瀬家住宅蔵","kana":"ひろせけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県習志野市津田沼6-5-11","lat":35.67804,"lng":140.021423,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0052","desc":"もと雑穀蔵で，主屋の南方に位置する。桁行４間，梁間２間半，東西棟，切妻造，桟瓦葺の平入２階建土蔵で，北面に幅１間の下屋を付けて蔵前をとる。外部は簓子下見で，内部の重厚な梁組にも見所がある。棟札から「大工棟梁鷺沼村邑山岩吉」が判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003390"},{"id":"00003389","register_sub_id":"101","register_pk":"104379","name":"廣瀬家住宅主屋","kana":"ひろせけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県習志野市津田沼6-5-11","lat":35.678127,"lng":140.021484,"geo_status":"db","era":"江戸末期／明治末期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0051","desc":"久々田本郷に所在した住居を店舗兼住居として現在地に移築。下手にあたる店舗部は改築されたが，上手部は１２畳半の広間と１０畳の納戸，４畳・６畳・６畳の座敷から成り，東面の式台跡や南面の縁などに房総民家の特徴をとどめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003389"},{"id":"00006513","register_sub_id":"101","register_pk":"107496","name":"紅屋商店主屋","kana":"べにやしょうてんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県館山市長須賀1","lat":34.98517534,"lng":139.86586435,"geo_status":"db","era":"昭和元頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0072","desc":"店舗東側に連続し，東西棟の切妻造，桟瓦葺，木造２階建で，南面西端に入母屋造の玄関を設ける。１階は８畳の仏間，２階は床・棚付の８畳の座敷と８畳の次の間からなる。店舗とほぼ同時期の建築で，店舗と繋がりをもった当時の住まいの形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006513"},{"id":"00001180","register_sub_id":"101","register_pk":"102170","name":"星野家薬局門","kana":"ほしのけやっきょくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県長生郡長南町長南2574","lat":35.39806642,"lng":140.23172404,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造，瓦葺，左右塀10m附属","structure_material":"木造","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0022","desc":"店舗の南に建つ棟門で、背後に控え柱をとる。通用口を開ける門左手の袖塀は店舗の庇南端に取り付き、 門右手の袖塀とともに門前に台形の呼び込み部をつくる。屋敷構えを構成する主要素であり、街道沿いの景観を整えるうえでも大きな役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001180"},{"id":"00016364","register_sub_id":"101","register_pk":"536431","name":"細谷家住宅主屋","kana":"ほそやけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県長生郡白子町幸治字新久890他","lat":35.42595,"lng":140.37943889,"geo_status":"db","era":"慶応2年（1866）／昭和23年改修、同49年移築","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造平屋建、茅葺、建築面積198㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"12 - 0337","desc":"九十九里浜南西の集落に位置する旧網元屋敷の主屋。敷地中央に南面して建つ、平屋建寄棟造平入茅葺で、南・西面は半繁垂木の軒天井を張る。食い違い四間取の農家建築で、西側の続き間座敷は北室に床、違棚、平書院を設える。茅葺屋根が地域景観をつくる民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016364"},{"id":"00006516","register_sub_id":"101","register_pk":"107499","name":"宮醤油店奥蔵","kana":"みやしょうゆてんおくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26185431,"lng":139.88531742,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0081","desc":"主屋の西方に位置する。桁行３間，梁間２間半，土蔵造２階建で，妻入の切妻造，桟瓦葺。小屋組は和小屋。住居施設の内蔵として建ち，２階床には格子状の通気孔を設け，家財道具を保管する。外壁は下見板張とし，重厚な外観で敷地西辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006516"},{"id":"00006522","register_sub_id":"101","register_pk":"107505","name":"宮醤油店主屋","kana":"みやしょうゆてんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.2617951,"lng":139.8854128,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0079","desc":"店舗の南方に連続して建つ。桁行５間半，梁間６間規模で，木造平屋建，桟瓦葺，寄棟造。内部は床の間を設けた８畳の座敷と畳の間４室を配し，南側に台所を張り出す。東側には庇付の玄関と勝手口を設け，動線を分ける。敷地内居住部分の中心的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006522"},{"id":"00006517","register_sub_id":"101","register_pk":"107500","name":"宮醤油店離れ","kana":"みやしょうゆてんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.261791,"lng":139.885315,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0080","desc":"主屋の南西方に位置する。木造平屋建，寄棟造，桟瓦葺。床の間と付書院を設けた１０畳の座敷と６畳間が南北に並び，東・南側に縁を廻し，東側に中庭を配す。両室とも天井が高く，四方柾や玉杢などの銘木を用い，欄間や床の間廻りの造作は優秀で，細工も精緻。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006517"},{"id":"00015292","register_sub_id":"101","register_pk":"532416","name":"宮本家住宅主屋","kana":"みやもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県千葉市中央区蘇我二丁目136-1","lat":35.57107778,"lng":140.12988611,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"12 - 0334","desc":"房総往還沿いに西面して建つ旧飼葉商の主屋。寄棟造妻入桟瓦葺で正側面に下屋を廻らす。内部は前土間で二室を並べ、南東に二室を接続し、全体に矩折平面とする。軒は出桁造で隅を緩やかに反上げ、棟に家紋と家名付の鬼瓦を飾り、街道沿いの繁栄を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015292"},{"id":"00012117","register_sub_id":"101","register_pk":"352916","name":"茂木七郎右衛門家住宅内門","kana":"もぎしちろうえもんけじゅうたくうちもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田字東中町337他","lat":35.94416422,"lng":139.86330987,"geo_status":"db","era":"明治後期／昭和46年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、銅板葺、間口2.1m、塀付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"12-262","desc":"主屋玄関の南東側に南向きに開き、左右に板塀を矩折れに延ばす。間口二・一メートルの腕木門、切妻造銅板葺で、板扉を両開きとする。本柱と棟束に女梁付の腕木を通し、軒は一軒疎垂木。板塀は竪板張で欄間を目透かしとする。主屋前庭を画す簡明な意匠の門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012117"},{"id":"00012114","register_sub_id":"101","register_pk":"352913","name":"茂木七郎右衛門家住宅奥文庫蔵","kana":"もぎしちろうえもんけじゅうたくおくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944491,"lng":139.863083,"geo_status":"db","era":"江戸後期／明治25年移築、平成22年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡、塀付","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-259","desc":"新座敷の背面側に建つ。東西棟の東妻に扉口を開き、内部はそれぞれ一室の二階建とする。桁行六・四メートル、梁間三・六メートルで、外壁は腰黒漆喰塗、上部白漆喰塗として軒まで塗込める。高梨周造家から移築されたと伝え、敷地の変遷を伝える土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012114"},{"id":"00012115","register_sub_id":"101","register_pk":"352914","name":"茂木七郎右衛門家住宅穀物蔵","kana":"もぎしちろうえもんけじゅうたくこくもつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944276,"lng":139.863557,"geo_status":"db","era":"明治前期／平成11年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積74㎡","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-260","desc":"屋敷地を画する塀の外側、琴平神社への参道脇に建つ。東西棟の桁行一〇・〇メートル、梁間七・二メートルで、建ちが高いが平屋建である。内部は旧は一室であったが、後に東西二室に区画し、東室は北面、西室は西妻面にそれぞれ入口を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012115"},{"id":"00012125","register_sub_id":"101","register_pk":"352924","name":"茂木七郎右衛門家住宅琴平蔵","kana":"もぎしちろうえもんけじゅうたくことひらぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田字東中町339他","lat":35.944571,"lng":139.863304,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積60㎡","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-270","desc":"本殿西方に建ち、祭礼時の道具等を収める。桁行七間半、梁間三間、切妻造桟瓦葺で南面に下屋を設け戸口を二所開く。外壁を漆喰塗として南面に庇付の高窓を二所配し、土戸両開とする。内部は土間で内壁に荷摺木を並べる。敷地の歴史的景観に寄与する大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012125"},{"id":"00012123","register_sub_id":"101","register_pk":"352922","name":"茂木七郎右衛門家住宅琴平神社額殿（絵馬殿）","kana":"もぎしちろうえもんけじゅうたくことひらじんじゃがくでん（えまでん）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944488,"lng":139.863504,"geo_status":"db","era":"明治29年","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.4㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-268","desc":"本殿と神楽殿の間に建ち、内外部に絵馬等を掲げる。桁行一間梁間二間、屋根は緩やかな起りを付けた切妻造で銅板を葺く。背面を板壁とする他は吹放ちで土間とし、板壁の前面に腰組を現した腰掛をつくる。本殿と同じ立川流大工の作で、丁寧な造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012123"},{"id":"00012122","register_sub_id":"101","register_pk":"352921","name":"茂木七郎右衛門家住宅琴平神社神楽殿","kana":"もぎしちろうえもんけじゅうたくことひらじんじゃかぐらでん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田339","lat":35.94441,"lng":139.86353,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-267","desc":"桁行一間梁間一間の正側面の床を張り出し、擬宝珠高欄を廻らして舞台とし、後方に控室を付ける。向唐破風造の照り起り屋根を架け妻入とする。兎毛通しに天狗面を彫刻し正面を飾る。内部は間仕切りに松羽目の鏡戸をたて、整った構えの神楽殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012122"},{"id":"00012124","register_sub_id":"101","register_pk":"352923","name":"茂木七郎右衛門家住宅琴平神社手水舎","kana":"もぎしちろうえもんけじゅうたくことひらじんじゃちょうずや","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944499,"lng":139.86364,"geo_status":"db","era":"明治5年／明治25年移築","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、銅板葺、面積2.2㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"12-269","desc":"本殿南東側に東西棟で建ち、桁行一間梁間一間、切妻造銅板葺である。四本柱を内転びに立て、頭貫で固めて木鼻を付し、台輪を廻す。組物は三斗、妻飾は虹梁大瓶束とし、破風に鰭付蕪懸魚を飾る。軒は二軒で屋根に強い照りを付ける。本格的な形式をもつ手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012124"},{"id":"00012121","register_sub_id":"101","register_pk":"352920","name":"茂木七郎右衛門家住宅琴平神社本殿","kana":"もぎしちろうえもんけじゅうたくことひらじんじゃほんでん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944592,"lng":139.863516,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-266","desc":"宅地隣の境内に南面して建つ。桁行二間梁間一間、前方一間吹放ち、向唐破風造の照り起り屋根を架け妻入とする。虹梁形頭貫を波紋籠彫の持送で受け、中備の透彫や板支輪など精緻な彫刻で充溢させ、笈形や兎毛通しなど立川流大工の技量が冴える近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012121"},{"id":"00012108","register_sub_id":"101","register_pk":"352907","name":"茂木七郎右衛門家住宅主屋","kana":"もぎしちろうえもんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944297,"lng":139.863136,"geo_status":"db","era":"明治中期／平成4年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積282㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-253","desc":"敷地北西寄りに南面する平屋建で、外壁を黒漆喰塗として重厚な趣をもつ。東西に長い主屋棟の南西端に土間棟を張り出し、背面中央に座敷棟を矩折れに建てる。玄関奥の七畳に床を備え、西隣に仏間を配する。座敷棟の各室も上質で往時の生活をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012108"},{"id":"00012109","register_sub_id":"101","register_pk":"352908","name":"茂木七郎右衛門家住宅書院","kana":"もぎしちろうえもんけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944417,"lng":139.863289,"geo_status":"db","era":"明治38年／平成7年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-254","desc":"主屋北面東端から渡廊下を介して建つ、東西に長い寄棟造で、南、東面に下屋を設ける。内部は東の上手から、上一五畳、中一五畳、書院九畳を並べて正側面に縁を廻らしガラス戸をたてる。座敷飾りや室境の透彫欄間、シャンデリアなど瀟洒な意匠の書院棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012109"},{"id":"00012119","register_sub_id":"101","register_pk":"352918","name":"茂木七郎右衛門家住宅書院北・東側土塀","kana":"もぎしちろうえもんけじゅうたくしょいんきた・ひがしがわどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田字東中町339他","lat":35.944516,"lng":139.863436,"geo_status":"db","era":"明治38年頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造、瓦葺、延長36m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"12-264","desc":"書院の北側と東側に矩折れに廻らす延長三六・二メートルの土塀で桟瓦を葺く。高さ四・四メートルと高く、東側土塀の南寄りを一段下げる。外側は控壁を設けて軒蛇腹をつくり、モルタル仕上げとし、内側は真壁で漆喰塗である。防犯、防火に備えた高塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012119"},{"id":"00012120","register_sub_id":"101","register_pk":"352919","name":"茂木七郎右衛門家住宅書院南側板塀","kana":"もぎしちろうえもんけじゅうたくしょいんみなみがわいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田字東中町338-1他","lat":35.944246,"lng":139.86347,"geo_status":"db","era":"明治後期／平成22年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長33m、門付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"12-265","desc":"書院南側の庭の東面と南面に廻らす板塀で、東面塀の中央に門口を開き、屋根は桟瓦葺。板塀は、外側を竪板張目板打、内側を鼠漆喰塗として腰に簓子下見板を張り、欄間は目透かしで横桟一本を通す。門は、棟門で透彫欄間を入れる。庭空間を彩る瀟洒な庭塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012120"},{"id":"00012112","register_sub_id":"101","register_pk":"352911","name":"茂木七郎右衛門家住宅新蔵","kana":"もぎしちろうえもんけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944395,"lng":139.862985,"geo_status":"db","era":"大正元年頃／平成22年改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-257","desc":"本蔵の背面側に東西棟の棟を並べて建つ土蔵。規模もほぼ同様で、桁行九・一メートル、梁間三・九メートルの二階建。小屋は叉首組と和小屋を混用し、屋根は切妻造桟瓦葺とする。外壁は腰下見板張、一階部は海鼠壁、上部は軒まで白漆喰で塗込める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012112"},{"id":"00012110","register_sub_id":"101","register_pk":"352909","name":"茂木七郎右衛門家住宅新座敷","kana":"もぎしちろうえもんけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944415,"lng":139.863101,"geo_status":"db","era":"大正元年頃／平成4年改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-255","desc":"主屋座敷棟の後方に東西棟で建ち、西端を新蔵の蔵前とし、東端は書院西面と渡廊下で繋ぐ。平面は平床と天袋付の床脇を備えた主室と次の間を並べて正側面に廊下を廻す。背面側は外壁を大壁または鉄板張とし、建具も鉄板張として防火対策が講じられた座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012110"},{"id":"00012116","register_sub_id":"101","register_pk":"352915","name":"茂木七郎右衛門家住宅正門","kana":"もぎしちろうえもんけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田字東中町337","lat":35.94398977,"lng":139.86356396,"geo_status":"db","era":"明治中期／平成20年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口3.2m、潜戸付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"12-261","desc":"路地の奥に西面して構える。間口四・三メートルの薬医門、切妻造桟瓦葺で板扉を両開きとし、南側に潜戸を設ける。五平の本柱をやや内寄りに立てて冠木を渡し、梁を架けて出桁を受ける。旧家の表門に相応しい、堅牢なつくりで重厚な趣を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012116"},{"id":"00012111","register_sub_id":"101","register_pk":"352910","name":"茂木七郎右衛門家住宅本蔵","kana":"もぎしちろうえもんけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944341,"lng":139.862998,"geo_status":"db","era":"江戸後期／平成22年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-256","desc":"主屋背面西寄りに建つ東西棟の土蔵。桁行九・一メートル、梁間四・九メートルの規模で、二階建。小屋組は叉首組と和小屋組を併用し、屋根は切妻造桟瓦葺。内部は一、二階とも板敷の一室とする。壁内に砂利を詰めるなど防火・防犯の対策を凝らした土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012111"},{"id":"00012113","register_sub_id":"101","register_pk":"352912","name":"茂木七郎右衛門家住宅向蔵","kana":"もぎしちろうえもんけじゅうたくむこうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県野田市野田339","lat":35.944219,"lng":139.862946,"geo_status":"db","era":"江戸後期／平成15年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-258","desc":"建物群の西南端に建つ土蔵。東面する南北棟で、東側に下屋を付す。内部は一、二階とも板敷一室とし、小屋は叉首組と和小屋を交互に用いる。屋根は切妻造桟瓦葺である。文政四年の野田大火の際と思われる焼損跡が残るなど、地域の歴史を今に伝える土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012113"},{"id":"00012118","register_sub_id":"101","register_pk":"352917","name":"茂木七郎右衛門家住宅煉瓦塀","kana":"もぎしちろうえもんけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市野田字東中町340-1他","lat":35.94451626,"lng":139.86318488,"geo_status":"db","era":"明治25年頃","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"煉瓦造、総延長19m、出入口付","structure_material":"煉瓦造","registered":"2018.03.27(平成30.03.27)","register_no":"12-263","desc":"新蔵と奥文庫蔵を矩の手に結ぶ西塀と奥文庫蔵から東に延びて敷地北辺を画す北塀からなり、新蔵側にアーチ積による出入口を開く。フランス積で要所に控壁を設け、頂部を蛇腹として桟瓦を葺く。四・二メートル超の高さを有し、屋敷内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012118"},{"id":"00007965","register_sub_id":"101","register_pk":"128798","name":"茂木本家住宅板塀","kana":"もぎほんけじゅうたくいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15他","lat":35.94355207,"lng":139.86540652,"geo_status":"db","era":"大正15／平成16改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、瓦葺、延長96m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0134","desc":"旧漬物蔵東端から通り沿いに敷地の北・東面を画し、延長９６ｍに及ぶ。柱間１．２ｍに方柱を建て、地覆や内法長押などで固め、竪板を張る。腕木で軒桁を持ち出し、疎垂木を配る。桟瓦葺。柿渋塗とし、落ち着きのある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007965"},{"id":"00007967","register_sub_id":"101","register_pk":"128800","name":"茂木本家住宅稲荷神社","kana":"もぎほんけじゅうたくいなりじんじゃ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"千葉県","address":"千葉県野田市野田字東下町242-10","lat":35.94348621,"lng":139.86473641,"geo_status":"db","era":"文化5","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積5.8㎡","structure_material":"土蔵造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0136","desc":"敷地西北隅の一郭を画し、稲荷神を祀る。桁行２．７ｍ梁間２．１ｍの土蔵造の社殿で、切妻造妻入桟瓦葺とする。内部は板敷で、棹縁天井、後寄りに壇を設け、三間社流造の厨子を安置する。外壁は漆喰仕上げで、正面には宝珠と神狐などの丁寧な鏝細工が飾られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007967"},{"id":"00007968","register_sub_id":"101","register_pk":"128801","name":"茂木本家住宅稲荷神社水屋","kana":"もぎほんけじゅうたくいなりじんじゃみずや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"千葉県","address":"千葉県野田市野田字東下町242-10","lat":35.94346067,"lng":139.86476078,"geo_status":"db","era":"文化5","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造、銅板葺、面積2.0㎡","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0137","desc":"社殿の東南に、南北棟で建つ。桁行一間梁間一間、切妻造銅板葺。内転びに建つ几帳面取の方柱を頭貫と台輪で固め、柱上三斗組とし、軒は二軒繁垂木。木鼻は唐獅子、中備や懸魚は神狐の彫刻で、西面は狐の嫁入りのモチーフとする。稲荷神社に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007968"},{"id":"00007958","register_sub_id":"101","register_pk":"128791","name":"茂木本家住宅北蔵","kana":"もぎほんけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94344239,"lng":139.86549965,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0127","desc":"主屋居室棟の東に位置する。東西棟の切妻造桟瓦葺、桁行７．７ｍ梁間６．８ｍの土蔵造２階建。外壁は漆喰仕上げで、柱型等を現す特徴的な外観を造る。南面に蔵前を設け、戸口を開く。南・東面には窓を穿ち、持送り付の庇を付け、両開戸を吊る。小屋はトラス組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007958"},{"id":"00007962","register_sub_id":"101","register_pk":"128795","name":"茂木本家住宅旧米倉","kana":"もぎほんけじゅうたくきゅうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94347112,"lng":139.86489555,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0131","desc":"旧仕込蔵の西北に東西棟で建つ。桁行１１ｍ梁間５．５ｍの木造。切妻造桟瓦葺で、南面に庇を設ける。外壁はモルタル塗で、腰を洗出し仕上げとし、旧漬物蔵と同様に外観を造る。東・西二室で、西半部を吹抜けとし、内部に鉄板を張り、東半部には２階を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007962"},{"id":"00007960","register_sub_id":"101","register_pk":"128793","name":"茂木本家住宅旧仕込倉","kana":"もぎほんけじゅうたくきゅうしこみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94328397,"lng":139.86499392,"geo_status":"db","era":"大正前期／平成15改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0129","desc":"主屋の西方、正門から車寄せへの通路を挟む位置に建つ。桁行２５ｍ梁間６．８ｍの南北に長い木造平屋建。入母屋造桟瓦葺。外壁をモルタル塗、腰を洗出し仕上げとし、妻面には小屋架構を現す。内部はモルタル床で、和小屋を見せる。醤油製造の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007960"},{"id":"00007961","register_sub_id":"101","register_pk":"128794","name":"茂木本家住宅旧漬物倉","kana":"もぎほんけじゅうたくきゅうつけものぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94350333,"lng":139.86516366,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0130","desc":"主屋の北に位置する。桁行１３ｍ梁間３．３ｍの木造平屋建。東西に長い切妻造桟瓦葺で、南面に奥行１．８ｍの庇を掛ける。庇正面を開放し、側面を壁とする。外壁はモルタル塗、腰を洗出し仕上げとする。内部を三室に分け、壁は杉板張。屋敷を構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007961"},{"id":"00007963","register_sub_id":"101","register_pk":"128796","name":"茂木本家住宅旧門番棟","kana":"もぎほんけじゅうたくきゅうもんばんとう","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94346938,"lng":139.8649826,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0132","desc":"正門と旧米蔵の間に位置する。南北棟の寄棟造桟瓦葺で、鉄板葺の庇を四周にまわす。桁行５．５ｍ梁間３．６ｍの木造平屋建。腰を下見板張とする漆喰仕上げで、東面に窓や戸口を開ける。内部は南に六畳の居室、北側には入口土間などを配する。門番所の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007963"},{"id":"00007957","register_sub_id":"101","register_pk":"128790","name":"茂木本家住宅主屋","kana":"もぎほんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94335448,"lng":139.86517062,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積488㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0126","desc":"南北棟の玄関棟を中心に、東面南寄りに客間棟、北寄りに居室棟を突き出す。桟瓦葺で、下屋庇が銅板葺。玄関棟の西面には車寄せ、南端に応接間を付設する。応接間はベイウィンドゥを付ける洋間で、客間棟にはトコなどを構える座敷を配する。良質な近代住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007957"},{"id":"00007964","register_sub_id":"101","register_pk":"128797","name":"茂木本家住宅正門","kana":"もぎほんけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94349991,"lng":139.86504585,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、瓦葺、間口2.7m、袖塀付","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0133","desc":"敷地北辺の西寄りに位置する。切妻造桟瓦葺の一間薬医門で、東・西に袖塀を付け、東袖塀に潜りを開ける。間口２．７ｍで、控柱は主柱より広く開ける。冠木上に男梁を架け、一軒疎垂木。装飾の少ない簡明な表門で、旧米蔵などとともに重厚な表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007964"},{"id":"00007966","register_sub_id":"101","register_pk":"128799","name":"茂木本家住宅庭門及び竹木賊張塀","kana":"もぎほんけじゅうたくにわもんおよびたけとくさばりへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94317777,"lng":139.86510969,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"門 木造、間口1.7m 塀 木造、板葺、延長9.3m","structure_material":"門 木造","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0135","desc":"主屋南西隅から西へ延び、主屋西側の通路と庭を区画する。西寄りに間口１．７ｍの庭門を構え、塀は延長９．３ｍを測る。塀は栩葺で、北面が竹木賊張、小壁漆喰塗で、南面が板張。門は磨丸太材による腕木門で銅板葺。瀟洒な庭門と塀で、品格ある構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007966"},{"id":"00007959","register_sub_id":"101","register_pk":"128792","name":"茂木本家住宅南蔵","kana":"もぎほんけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東下町242-15","lat":35.94337276,"lng":139.86552142,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0128","desc":"北蔵の南に南北棟で建つ。切妻造桟瓦葺の土蔵造２階建、桁行７．７ｍ梁間６．８ｍ。外壁は漆喰仕上げで、柱型などを現す。西面に蔵前を設け、出入口とし、東面には各階２ヶ所に窓を穿つ。同規模・同形式の二つの蔵が直角に建ち並び、敷地東面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007959"},{"id":"00007969","register_sub_id":"101","register_pk":"128802","name":"茂木本家住宅煉瓦塀","kana":"もぎほんけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田字東下町242-10","lat":35.94355528,"lng":139.86472944,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、総延長26m","structure_material":"煉瓦造","registered":"2010.01.15(平成22.01.15)","register_no":"12 - 0138","desc":"稲荷神社の北面から東面にかけて、道路沿いに設けられる塀。折曲り延長２６ｍ。石積基礎上、フランス積とし、上部は小屋根状に造る。西側１０ｍが高さ４．３ｍ、東側が高さ３．５ｍで、西側は厚く、南面に柱型を造り出す。板塀と対照的な重厚な景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007969"},{"id":"00012507","register_sub_id":"101","register_pk":"367802","name":"會田家住宅旧蔵","kana":"あいだけじゅうたくきゅうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都葛飾区鎌倉三丁目36","lat":35.747871,"lng":139.878372,"geo_status":"geocoded","era":"昭和3年／平成29年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"13 － 0414","desc":"新中川と江戸川に挟まれたかつての農村地帯にあり、敷地東方に建つ蔵。南北棟の切妻造で、四周に一間幅の下屋を廻し、南面の妻には庇付の窓を設ける。農作業や米の貯蔵に使用され、北面の貯蔵庫は鉄筋コンクリート造で堅牢につくる。農家の生業を支えた蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012507"},{"id":"00004339","register_sub_id":"101","register_pk":"105329","name":"青柳家住宅主屋","kana":"あおやぎけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都練馬区羽沢1-6-12","lat":35.74087135,"lng":139.67009865,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"13 － 0180","desc":"道路に北面する敷地の中央に建つ。寄棟造，瓦葺の木造平屋建で，北面中央に玄関，玄関東に応接室を設ける。６畳茶の間の回りに８畳座敷や台所を配した簡明な平面と，水平線を強調した軒廻りのライト風意匠に特徴。昭和初期開発の私鉄沿線住宅地遺構の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004339"},{"id":"00004949","register_sub_id":"101","register_pk":"105939","name":"浅田家住宅主屋","kana":"あさだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都目黒区目黒4-19-4","lat":35.634373,"lng":139.700562,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"13 － 0189","desc":"切妻造，赤色フランス瓦葺下見板張の一間洋館を入母屋造の玄関脇に配置した端正な和風住宅。和風部は寄棟造，桟瓦葺で，南側に縁側と８畳座敷２室を置き，北側に台所，６畳茶の間，４畳半納戸などを並べる。昭和初期東京近郊における中流住宅の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004949"},{"id":"00004530","register_sub_id":"101","register_pk":"105520","name":"芦葉家住宅倉庫","kana":"あしばけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区千駄木3-9-1","lat":35.72709372,"lng":139.76159938,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積11㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"13 － 0184","desc":"西側及び南側が接道する敷地の北西隅に東面して建つ。鉄筋コンクリート造２階建で陸屋根とし，柱梁による構造をとる。昭和初期に土蔵に代わり普及した鉄筋コンクリート造倉庫の遺構で，当時の鉄筋コンクリート技術を知る上で貴重。設計は小島栄吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004530"},{"id":"00004531","register_sub_id":"101","register_pk":"105521","name":"芦葉家住宅門","kana":"あしばけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区千駄木3-9-1","lat":35.72701921,"lng":139.76160955,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造、間口4.0m、鉄製門扉付","structure_material":"石造","registered":"2005.02.09(平成17.02.09)","register_no":"13 － 0185","desc":"敷地西端南寄りに，道路から後退して建つ。小松石瘤出し仕上げの門柱は，同種石材びしゃん仕上の柱頭飾りを載せ，装飾的な門扉が門柱間に２枚，門柱北側に１枚付く。門柱，門扉とも創建当初のもので，昭和初期に開発された住宅地の面影を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004531"},{"id":"00009924","register_sub_id":"101","register_pk":"196071","name":"新井家住宅内蔵","kana":"あらいけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都調布市入間町1-4","lat":35.65280324,"lng":139.58488153,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0339","desc":"主屋の座敷裏手に蔵前座敷を挟んで接する旧文庫蔵。桁行三間梁間二間、土蔵造二階建、平入で、屋根は切妻造、置屋根式の鉄板葺である。西妻面二階の窓に土戸を開き、庇を付ける。外壁は土壁で、鉢巻を廻らす。小屋組は登梁形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009924"},{"id":"00009926","register_sub_id":"101","register_pk":"196073","name":"新井家住宅旧蚕室","kana":"あらいけじゅうたくきゅうさんしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都調布市入間町1-4","lat":35.65248599,"lng":139.58511271,"geo_status":"db","era":"明治中期／昭和中期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積41㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0341","desc":"外蔵の東隣に東西棟で並び建つ。木造二階建、切妻造鉄板葺で、周囲にガラス戸をたて、腰を下見板張とする。戦後に転用された際に内部に間仕切や天井が設けられているが、小屋組等は当初の構造をよく残す。都内近郊の近代における養蚕業の様子を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009926"},{"id":"00009923","register_sub_id":"101","register_pk":"196070","name":"新井家住宅主屋","kana":"あらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都調布市入間町1-4","lat":35.65269413,"lng":139.58502103,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積128㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0338","desc":"屋敷林に囲まれた敷地中央に南東面して建つ木造平屋建で、屋根は寄棟造茅葺（鉄板仮葺）である。右手を土間とし、床上部は前列にヒロマとナカノマ、後列にチャノマ、ヘヤ、オクノマを並べる。座敷南西面に縁を廻らす。武蔵野の旧家の佇まいを伝える民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009923"},{"id":"00009437","register_sub_id":"101","register_pk":"194230","name":"新井家住宅主屋","kana":"あらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都新宿区北山伏町2","lat":35.69985368,"lng":139.72957284,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋一部2階建、瓦葺、建築面積346㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"13 － 0292","desc":"木造二階建、建築面積三四六平方メートル、和館、洋館からなる住宅建築。和館は紫檀、黒檀、鉄刀木など銘木により床の間、書院を豪華な空間とし、洋館は屋根を上質のフランス瓦、外壁をルスティカ積み、スクラッチタイル張りで仕上げ風格ある外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009437"},{"id":"00009925","register_sub_id":"101","register_pk":"196072","name":"新井家住宅外蔵","kana":"あらいけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都調布市入間町1-4","lat":35.65243179,"lng":139.58497752,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0340","desc":"主屋と前庭を挟み北面して建つ。桁行三間梁間二間半、土蔵造二階建、平入で、屋根は切妻造、置屋根式の鉄板葺である。外壁はモルタル洗出しとし鉢巻と水切を廻らす。東妻面上部に屋号を表し、西面には小窓を穿つ。二階に三重梁の小屋を組む、旧穀物蔵の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009925"},{"id":"00009927","register_sub_id":"101","register_pk":"196074","name":"新井家住宅中門及び塀","kana":"あらいけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都調布市入間町1-4-3","lat":35.65258768,"lng":139.58495205,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"中門 木造、鉄板葺、間口1.5m 塀 木造、鉄板葺、総延長8.5m","structure_material":"中門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0342","desc":"主屋前面から西側にのびる門と塀である。中門は間口一・五メートルの腕木門で、庭側に控柱を立てる。柱間に板戸を内開きとし、屋根は切妻造鉄板葺である。塀は竪板張目板打ちとし、屋根は鉄板葺とする。前庭と主庭を区画し、屋敷内の庭景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009927"},{"id":"00004215","register_sub_id":"101","register_pk":"105205","name":"淡島家住宅主屋","kana":"あわしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市井の頭4-23-11","lat":35.69873052,"lng":139.57590268,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"13 － 0178","desc":"北を井の頭公園に接する敷地の北東寄りに建つ。木造２階建で，屋根は赤色系の桟瓦葺である。ハーフティンバー風の外観と，ステインドグラスや装飾金物を用いた室内意匠に特徴がある。井の頭線開通に伴い住宅地化が進んだ井の頭地区に残る住宅遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004215"},{"id":"00004213","register_sub_id":"101","register_pk":"105203","name":"安藤家住宅主屋","kana":"あんどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市井の頭三丁目24-1","lat":35.696316,"lng":139.581802,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"13 － 0176","desc":"北・東が接道する敷地の北東寄りに東面して建ち，南に庭を置く。木造平屋建で，屋根は桟瓦葺及び鉄板葺の切妻屋根で構成され，外壁を漆喰塗とする。早大教授吉田享二の設計になり，昭和初期井の頭地区における住宅地開発の様子を示す建造物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004213"},{"id":"00005929","register_sub_id":"101","register_pk":"106914","name":"池上家住宅主屋","kana":"いけがみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区桜一丁目651","lat":35.645687,"lng":139.636566,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"13 － 0210","desc":"敷地北寄りに建つ東西棟で，２階屋根を切妻造，スペイン瓦葺とし，２階南面にサンルームを張り出す。外壁はリシン吹付で西面に突出した玄関ポーチ等に秩父石を張る。内部はアール・デコの意匠を良好に維持する。昭和初期の小規模洋風住宅の佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005929"},{"id":"00015415","register_sub_id":"101","register_pk":"533430","name":"池田家住宅主屋","kana":"いけだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区目白台三丁目32","lat":35.71558056,"lng":139.72430556,"geo_status":"db","era":"大正4年頃／大正10年・昭和10年増築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積144㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0524","desc":"目白通り北側の住宅地に位置する元鉄道監察官の住宅主屋。東の玄関から西の続き間座敷に至り、玄関の北に洋室棟、南に台所・浴室棟を付し、全体Ｌ字の平面とする。座敷は床脇に天袋・地袋を備え、床柱に鉄刀木を用いるなど材料吟味し、上質な近代和風の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015415"},{"id":"00012307","register_sub_id":"101","register_pk":"531631","name":"砂金家長屋","kana":"いさごけながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都豊島区雑司が谷三丁目32-4","lat":35.72119167,"lng":139.714625,"geo_status":"db","era":"昭和7年頃／平成20年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、金属板葺、建築面積145㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-413","desc":"雑司ヶ谷鬼子母神堂の参道に西面して建つ。棟割で五軒を設け、当初は一階に仕事場と座敷、二階に和室二室を配していた。正面は陸屋根風のモルタル洗出し仕上で、二階窓や頂部の帯状の金属張が水平性を強調する。昭和モダンの流行を伝える長屋建の店舗兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012307"},{"id":"00003849","register_sub_id":"101","register_pk":"104839","name":"石川酒造雑蔵","kana":"いしかわしゅぞうざつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.718765,"lng":139.33249592,"geo_status":"db","era":"明治31頃","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積133㎡、北面庇付","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0168","desc":"屋敷南辺のほぼ中央，街路沿いにある。２階建の土蔵造で，東西棟の切妻造，桟瓦葺の屋根は置屋根式とし，北面に下屋庇をつける。現在は資料館等に活用されているが，もとは米蔵で，明治期の屋敷構成の有様を示すとともに，歴史的な街路景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003849"},{"id":"00003850","register_sub_id":"101","register_pk":"104840","name":"石川酒造長屋門","kana":"いしかわしゅぞうながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.71885192,"lng":139.332367,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0169","desc":"雑蔵の北，街路より奥まった位置に南面して建つ。入母屋造，銅板葺で，中央を門口，左右を部屋とする。柱は礎石建，真壁造で，上部は漆喰仕上げ，腰は板で覆う。軒は正面のみ出桁造，小屋組は叉首組である。江戸期における武蔵野の農家の面影を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003850"},{"id":"00003851","register_sub_id":"101","register_pk":"104841","name":"石川酒造文庫蔵","kana":"いしかわしゅぞうぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.71893592,"lng":139.33248553,"geo_status":"db","era":"文久3","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0170","desc":"長屋門の東にあり，内部階段に残る墨書から，建築年代ともと宝蔵であったことがわかる。東西棟の切妻造，桟瓦葺，２階建の土蔵造で，西面の扉口に庇を架ける。規模は桁行６．３ｍと小さいが，柱を密に立て，丁寧な漆喰仕上げとするなど，つくりは上質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003851"},{"id":"00005111","register_sub_id":"101","register_pk":"106101","name":"市田家住宅裏門","kana":"いちだけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区上野桜木一丁目26","lat":35.72014057,"lng":139.77089012,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、鉄板葺、間口1.5m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"13 － 0194","desc":"主屋東北方の台所勝手口に対応した門で，屋敷地北辺の東寄りに位置する。間口１．５ｍ規模，切妻造，鉄板葺の腕木門で，引き違いの板戸を建て込み，鴨居棟木間中央に照明器具を吊る。腕木に刳形を付けるなど気を遣ったつくりで，屋敷背面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005111"},{"id":"00005110","register_sub_id":"101","register_pk":"106100","name":"市田家住宅表門","kana":"いちだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区上野桜木一丁目26","lat":35.71994466,"lng":139.7709752,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、瓦葺、間口2.0m、袖塀付","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"13 － 0193","desc":"主屋玄関の南に東西棟で建つ。間口１間，切妻造，桟瓦葺の腕木門で，上部の小壁に横長の連子窓を嵌め込み，柱・腕木・垂木等に面を取るなど丁寧なつくり。南面道路からやや後退して建ち，上部黒漆喰塗，腰縦板張，板葺の袖塀を従えて瀟洒な表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005110"},{"id":"00005109","register_sub_id":"101","register_pk":"106099","name":"市田家住宅蔵","kana":"いちだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区上野桜木一丁目26","lat":35.72006114,"lng":139.77083676,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木骨煉瓦造2階建、瓦葺、建築面積25㎡","structure_material":"木骨煉瓦造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"13 － 0192","desc":"主屋８畳座敷の北側を蔵前とし，南北棟で建つ。桁行２間半，梁間２間，寄棟造，桟瓦葺，妻入，２階建で，１階を仏間とする。木造軸部の外側に煉瓦を厚１枚半に積み，外部を人造石仕上げとし，石目地を切るのが特徴。主屋と同じ清水組の施工と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005109"},{"id":"00005108","register_sub_id":"101","register_pk":"106098","name":"市田家住宅主屋","kana":"いちだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区上野桜木一丁目26","lat":35.72005062,"lng":139.77095238,"geo_status":"db","era":"明治40／大正初期増築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"13 － 0191","desc":"日本橋布問屋の隠宅として建設。寄棟造，桟瓦葺，外壁押縁下見板張の木造２階建で，６畳と８畳座敷を東西に並べて西と南面に縁を廻し，東側南北に玄関・茶の間・台所を配し，座敷上部に２階を増築する。当時の住宅間取実例図集に掲載された和風住宅の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005108"},{"id":"00009436","register_sub_id":"101","register_pk":"194229","name":"一水寮","kana":"いっすいりょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都新宿区横寺町31-13","lat":35.702345,"lng":139.73521194,"geo_status":"db","era":"昭和26年／昭和30年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積96㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"13 － 0291","desc":"神楽坂の裏通りに、大工寮として昭和前期に建つ。材に贅を凝らしたものではないが、鑿、手斧の大工技法が格子や意匠梁の随所に見られ、当時の大工の技能を高さを現在にあらわす。戦後復興した神楽坂の町並みを構成し、裏通りの景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009436"},{"id":"00013357","register_sub_id":"101","register_pk":"368445","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都杉並区久我山五丁目275-10","lat":35.68820278,"lng":139.60213889,"geo_status":"db","era":"昭和28年／昭和30年・同42年増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"コンクリートブロック造一部木造2階建、建築面積157㎡","structure_material":"コンクリートブロック造一部木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0435","desc":"住宅金融公庫利用のコンクリートブロック造住宅に順次増築した。一階は中廊下の南に居室を並べ、施主の意向で二階に書斎を配す。外回りの建具は天井高一杯の引戸とし、ガラス障子とガラリ戸を多溝の鴨居に建込む。戦後モダニズム住宅の展開を示す建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013357"},{"id":"00010928","register_sub_id":"101","register_pk":"208899","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都大田区東雪谷五丁目1008-4","lat":35.589821,"lng":139.694332,"geo_status":"db","era":"昭和38","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"木造2階鉄筋コンクリート造地下1階建、鉄板葺、建築面積125㎡","structure_material":"木造2階鉄筋コンクリート造地下1階建","registered":"2016.02.25(平成28.02.25)","register_no":"13-0361","desc":"斜面地にある敷地形状にあわせた台形平面を持ち、鉄筋コンクリート造の車庫等の上部に木造二階建の家屋を載せる。二階バルコニーと一階の大開口が印象的で、内装の化粧ベニヤ板の使用、円柱を独立して建てる手法などにもレーモンド事務所の設計の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010928"},{"id":"00005261","register_sub_id":"101","register_pk":"106249","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市井口3-18-8","lat":35.69418304,"lng":139.53916907,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"13 － 0197","desc":"東面敷地の北寄りに建ち，桁行７間，梁間６間半，木造平屋建，寄棟造，桟瓦葺とする。規模の比較的大きな入母屋屋根の玄関を付属し，各室は廊下で連絡され，南側に居室をまとめる。８畳間を連続し続き間座敷の形式をとる。昭和初期の郊外住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005261"},{"id":"00013965","register_sub_id":"101","register_pk":"508225","name":"今井家住宅蔵","kana":"いまいけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片二丁目10-15","lat":35.71491389,"lng":139.75673611,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、瓦葺、建築面積21㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0450","desc":"本郷通り西側住宅地にある鉄筋コンクリート造地上二階地下一階、切妻造桟瓦葺の土蔵意匠の建物で、窓にシャッターを備える。内部中央に手摺付の階段を配し、地下は一回り広い平面としてガラスブロックで自然光を取入れる。都市住宅の近代的倉庫建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013965"},{"id":"00014459","register_sub_id":"101","register_pk":"512443","name":"岩田家住宅和館","kana":"いわたけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都台東区池之端四丁目219-7他","lat":35.71939722,"lng":139.7692,"geo_status":"db","era":"明治末期／大正9年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0475","desc":"池之端の三段坂に北面する住宅の和館で、東側に洋館を接続する和洋並列の住宅。寄棟造桟瓦葺、北西隅に客用玄関を配し、床構え付座敷や茶室を中廊下で繋いで構成する。内部意匠は華美にならず伝統的で明治らしい和風の応接空間。往時の住宅地の景観を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014459"},{"id":"00004532","register_sub_id":"101","register_pk":"105522","name":"位田家住宅主屋","kana":"いんでんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区田園調布3-12-11","lat":35.59935152,"lng":139.66394093,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"13 － 0186","desc":"西側を接道する敷地の北西寄りに建つ。木造桟瓦葺２階建。玄関脇の応接間や中廊下形式の間取りは昭和初期の中流住宅の典型を示すとともに、和洋折衷を基調とする目板付縦板張，上部白漆喰塗の外観は，田園調布における住宅地形成の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004532"},{"id":"00006295","register_sub_id":"101","register_pk":"107278","name":"宇津木家住宅主屋","kana":"うつきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都青梅市西分町2-80","lat":35.78908904,"lng":139.26327976,"geo_status":"db","era":"明治25／明治41改修・昭和15曳家","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積117㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"13 － 0215","desc":"旧青梅宿の東方，青梅街道に北面して建つ。切妻造，平入の２階建で，正面に半間の下屋庇を設ける。史料から大屋根はもと杉板葺，ほかは杉皮葺とわかる。表の建具等は変更しているが，全体的に旧態をよく留めており，当地における明治期の町家形式を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006295"},{"id":"00014760","register_sub_id":"101","register_pk":"519018","name":"梅田家（沖五郎）住宅石倉及び外便所","kana":"うめだけ（おきごろう）じゅうたくいしぐらおよびそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都新島村本村三丁目265","lat":34.37450278,"lng":139.25785833,"geo_status":"db","era":"昭和24年頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"石造2階建一部平屋建、石葺、建築面積30㎡","structure_material":"石造2階建一部平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0505","desc":"本村東側に位置する漁家の石倉及び外便所。コーガ石を用いた二階建切妻造平入石葺の南北棟。南側に石造の外便所が取り付く。内部は各階１室で１階は土間の物置、2階は床構え付き座敷で西と東に窓を開ける。通りに面して建ち、地域の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014760"},{"id":"00014751","register_sub_id":"101","register_pk":"519009","name":"梅村家住宅（旧山崎家住宅）主屋","kana":"うめむらけじゅうたく（きゅうやまざきけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片一丁目10-595","lat":35.71289444,"lng":139.75611389,"geo_status":"db","era":"昭和2年／昭和5年増築、令和2年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部銅板葺、建築面積121㎡","structure_material":"木造平屋一部2階建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0496","desc":"東京大学西方の市街地に位置する和風住宅の主屋。平屋建入母屋造桟瓦葺の東西棟で、東の入母屋造玄関から片廊下を延ばし、北に二列四室を並べ、西端を切妻造銅板葺の二階建とする。二階座敷には高欄を付し南庭を望む。閑静な住宅街に残る良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014751"},{"id":"00014752","register_sub_id":"101","register_pk":"519010","name":"梅村家住宅（旧山崎家住宅）門","kana":"うめむらけじゅうたく（きゅうやまざきけじゅうたく）もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片一丁目10-595","lat":35.71281111,"lng":139.75621389,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、間口1.8m","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0497","desc":"主屋の正面に位置し、通りに東面する切妻造平入銅板葺の腕木門。角柱の主柱を礎石上に立てて棟木まで延ばし、腕木で軒桁を支持する。軒は一軒疎垂木。門口には両開の板戸を吊り、欄間に格子を入れる。通りに面して建ち、閑静な住宅地の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014752"},{"id":"00013972","register_sub_id":"101","register_pk":"508232","name":"沖本家住宅洋館","kana":"おきもとけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国分寺市内藤二丁目43-9","lat":35.69868333,"lng":139.45179167,"geo_status":"db","era":"昭和8年／同15年・令和2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積98㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0457","desc":"国分寺崖線上に建つ住宅。木造二階建、半切妻造金属板葺で、外壁は下見板張、南面二階と玄関ポーチ上部を黄土色の掻落土壁とする。中廊下式で南に居室、北に水廻りを配し、天井に梁形を現す居間に石張暖炉を設ける一方、引違窓や和室を持つ瀟洒な洋風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013972"},{"id":"00013973","register_sub_id":"101","register_pk":"508233","name":"沖本家住宅和館","kana":"おきもとけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国分寺市内藤二丁目43-9","lat":35.69859722,"lng":139.45168333,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0458","desc":"洋館の東側に渡廊下で接続する和館。木造平屋建、桟瓦葺で北を切妻、南を入母屋造、軒浅く霧除庇を廻す。続き間座敷の南のサンルームと西の広縁に大判ガラス戸を建て、皮付や絞りの丸太を用いて全体に落着いた意匠の数寄屋風にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013973"},{"id":"00016498","register_sub_id":"101","register_pk":"574860","name":"樫尾俊雄発明記念館（旧樫尾家住宅主屋）","kana":"かしおとしおはつめいきねんかん（きゅうかしおけじゅうたくおもや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和後","pref":"東京都","address":"東京都世田谷区成城四丁目511-1他","lat":35.63886694,"lng":139.59385389,"geo_status":"db","era":"昭和47年／平成25年改修","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積265㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"13 - 0529","desc":"国分寺崖線の上に建つ発明家樫尾俊雄の旧宅。設計は滝沢健児。鉄筋コンクリート造二階建、切妻造銅板葺。外壁はモルタル吹付で一部は窯変タイル貼。切妻の屋根は起り付とし、妻面を正・背面とも大きく張出す軽快な意匠。屋根に独自の作風を示す滝沢の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016498"},{"id":"00013356","register_sub_id":"101","register_pk":"368444","name":"数江家住宅主屋","kana":"かずえけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区久が原二丁目899","lat":35.58392778,"lng":139.69486667,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋一部2階建一部地階付、瓦葺、建築面積307㎡","structure_material":"木造平屋一部2階建一部地階付","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0434","desc":"郊外住宅地、久が原の高台に建つ。平屋建の玄関茶室棟と二階建の居室棟が雁行して連なる。接道する西正面はスパニッシュ風に整えるが全体は上質な数寄屋趣味で、茶事に供する室を用意する。応接間と二階居室のみ洋室とする。和風要素が強い郊外住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013356"},{"id":"00000954","register_sub_id":"101","register_pk":"101944","name":"金澤家住宅主屋","kana":"かなざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片2-2-7","lat":35.71391798,"lng":139.75618297,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造２階建，瓦葺及金属板葺，建築面積200㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0045","desc":"良好な住宅地として知られる本郷西片地区の面影を伝える昭和初期住宅のひとつ。東京美術学校建築科の助教授であった金澤庸治が父親のために建てた住宅で，２階建の主屋のみ棟を東西方向に振っているのが特徴。施工は清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000954"},{"id":"00000956","register_sub_id":"101","register_pk":"132574","name":"金澤家住宅門及び塀","kana":"かなざわけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片2-2-7","lat":35.71398578,"lng":139.75605554,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造瓦葺門，板塀延長10.7m附属","structure_material":"木造瓦葺門","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0047","desc":"木造瓦葺の棟門で，左右に土台建ち，高欄風の平桁・架木を載せた竪羽目の板塀を付ける。門扉の上部に菱組格子を，冠木上には繊細な組子による欄間を入れる。門，塀とも確かなプロポーションをもち品格ある構えをつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000956"},{"id":"00000955","register_sub_id":"101","register_pk":"101945","name":"金澤家住宅洋館","kana":"かなざわけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区西片2-2-7","lat":35.71400211,"lng":139.75615438,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建，金属板葺，建築面積29㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0046","desc":"板塀に沿って建てられた平屋建，下見板張りの洋館で，北西面の外壁と屋根の一部をガラス張りとしていることから一見してアトリエの造りと解る。切妻屋根の右手の寄棟部は応接室。建築設計事務所兼自宅を意図したものとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000955"},{"id":"00007878","register_sub_id":"101","register_pk":"108858","name":"鎌田家住宅主屋","kana":"かまたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区梅丘1-1473-5","lat":35.65277952,"lng":139.6521871,"geo_status":"db","era":"昭和7／昭和47改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0249","desc":"通りに東面する敷地の中央に建つ。木造平屋建、建築面積１０４㎡。東西棟の入母屋造を中心に、入母屋造妻入の玄関を東に、北にもと陸屋根の洋間、南に寄棟造の和室を配し、変化に富む外観をつくる。中廊下式の住居で、戦前東京の私鉄沿線に建つ郊外住宅の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007878"},{"id":"00007879","register_sub_id":"101","register_pk":"108859","name":"鎌田家住宅離れ","kana":"かまたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区梅丘1-1473-5","lat":35.65275468,"lng":139.65203638,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0250","desc":"敷地の西奥に建つ。主屋と雁行して繋がる奥座敷で、木造平屋建、建築面積５０㎡。南北棟の入母屋造桟瓦葺で、銅板葺庇を付ける。トコや棚、付書院を構える十畳と六畳次の間からなり、庭側に主屋から槫縁がまわる。主屋と連続し、変化のある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007879"},{"id":"00007880","register_sub_id":"101","register_pk":"108860","name":"鎌田家住宅門及び塀","kana":"かまたけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区梅丘1-1473-5","lat":35.65269826,"lng":139.65229646,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"門 鉄筋コンクリート造、間口2.6m、塀 鉄筋コンクリート造、延長4.0m","structure_material":"門 鉄筋コンクリート造","registered":"2009.11.02(平成21.11.02)","register_no":"13-0251","desc":"通りから２ｍ下がって東面して門を構える。間口２．６ｍに方柱を建て、その両側に各２．０ｍの袖塀を付け、北袖塀に潜りを開ける。鉄筋コンクリート造の洗出し仕上げ。塀は柱形を表し、その間を赤色にしており、緑豊かな郊外住宅地の景観要素として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007880"},{"id":"00014326","register_sub_id":"101","register_pk":"511315","name":"亀井家住宅主屋","kana":"かめいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区松原一丁目129-7","lat":35.66714722,"lng":139.6524,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"13 - 0465","desc":"住宅街に広い庭園をもつ洋館付二階建和風住宅。入母屋造桟瓦葺で、洋館は切妻造フランス瓦葺。玄関を東面道路に向け、玄関脇に洋館、東西に中廊下平面とする。中央続き間座敷の東西に階段を配して動線を公私で分け、各所に覗き窓を配し、要人の応接に備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014326"},{"id":"00013236","register_sub_id":"101","register_pk":"366225","name":"川井家住宅主屋","kana":"かわいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都多摩市鶴牧二丁目22-2他","lat":35.61836667,"lng":139.41528611,"geo_status":"db","era":"明治18年頃／昭和30年頃増築、同57年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積199㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"13 － 0432","desc":"鶴牧西公園に隣接するもと名主宅。建ちの高い入母屋造茅葺平屋建で、小屋内に二層の蚕室を設ける。内部は西半を床上部とし、座敷は差鴨居を多用し柱を省略する。東半の土間を二分し、南面に戸口を二つ開く。市街化著しい多摩地域に残る貴重な大型養蚕農家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013236"},{"id":"00005936","register_sub_id":"101","register_pk":"106921","name":"河津家住宅主屋","kana":"かわづけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区成城三丁目10-29","lat":35.63766288,"lng":139.5940395,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"13 － 0214","desc":"簡明な矩形平面の２階建で，寄棟屋根中央に小屋裏居室の屋根窓を見せる。平滑なモルタル塗外壁に弓形，台形の出窓や玄関キャノピーが変化を与える。１階南面中央に居間と食堂を置き，各個室を洋室とする。内部を軽快なアール・デコ風とする中流階層の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005936"},{"id":"00001499","register_sub_id":"101","register_pk":"102489","name":"河原家住宅主屋","kana":"かわはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都大田区南馬込1-55-8","lat":35.59050876,"lng":139.71088479,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建塔屋付、瓦葺、建築面積123㎡","structure_material":"木造平屋建塔屋付","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0070","desc":"明治１８年建設の旧馬込小学校の玄関と教場部分を移築して和風住宅に改造，その後昭和３８年に，同校新校舎の時計台（大正１４年建設）を移築して主屋の書斎の上部に設置した。学校建築を活用した時計台のある特異な住宅として地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001499"},{"id":"00003645","register_sub_id":"101","register_pk":"104635","name":"菊池寛実記念智美術館別館","kana":"きくちかんじつきねんともびじゅつかんべっかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都港区虎ノ門4-1-35","lat":35.66597093,"lng":139.74426378,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、スレート葺、建築面積188㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"13 － 0163","desc":"もと実業家の邸宅の洋館部分。木造で，中央部が２階建になり，スレート葺の複雑な屋根を架ける。基礎は小松石成層乱積で，漆喰塗の外壁は要所に煉瓦タイルを張り，ステインドグラスや当初の建具もよく残り，当時の造形と意匠の傾向を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003645"},{"id":"00011079","register_sub_id":"101","register_pk":"205186","name":"菊池家住宅茶室","kana":"きくちけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"昭和40／昭和44改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"13 - 0362","desc":"堀口捨己晩年の作。鉤の手状敷地の隅に軸を振って建つ。南面して三畳台目と八畳広間の二つの茶室、間に水屋三畳を配す。クリを多用し、広間は桟を設けないガラス戸として外部簀子縁に空間を連続させる。照明と空調を組み込んだ天井などにも、堀口の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011079"},{"id":"00011080","register_sub_id":"101","register_pk":"205187","name":"菊池家住宅茶室待合","kana":"きくちけじゅうたくちゃしつまちあい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"昭和40","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.1㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"13 - 0363","desc":"茶室の南西方に位置する。茶室南面に対して斜めに相対し、敷地南側の庭を眺めることができる。南寄り二間分を腰掛けとし、北半は北面に入口を設けてする砂雪隠を配する。屋根は銅板葺で、丸垂木を疎に配すなど、瀟洒な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011080"},{"id":"00011081","register_sub_id":"101","register_pk":"205188","name":"菊池家住宅茶室門及び塀","kana":"きくちけじゅうたくちゃしつもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"昭和40","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"門 石造及び鉄筋コンクリート造、間口3.1m 塀 石造及び鉄筋コンクリート造、総延長52m、車庫付","structure_material":"門 石造及び鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"13 - 0364","desc":"敷地西側の緩やかな坂に沿って段状をなす石塀と門。片引大戸の門は茶室造作と同じく栗材を用い、手斧ハツリ仕上。塀は白川石を深目地に積んでおり、大きさを違えた石を、水平線垂直線の構成を意識して配置するなど、堀口捨己の設計意図が反映されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011081"},{"id":"00014761","register_sub_id":"101","register_pk":"519019","name":"紀野家住宅主屋","kana":"きのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都新島村本村四丁目646他","lat":34.37254722,"lng":139.257825,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、石葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0506","desc":"本村東側に位置する漁家の主屋。敷地北寄りに南面する木造平屋建入母屋造石葺で、側廻りにコーガ石を積み木造トラスを組む。内部は西を土間、東を田の字形に部屋を配し、南東に床と仏壇を構える。間取りや石葺屋根など新島の伝統的民家の特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014761"},{"id":"00014762","register_sub_id":"101","register_pk":"519020","name":"紀野家住宅釜屋形","kana":"きのけじゅうたくかまやかた","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都新島村本村四丁目646他","lat":34.37256944,"lng":139.25778333,"geo_status":"db","era":"昭和前期／昭和23年頃・同40年頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造平屋建、鉄板葺、建築面積19㎡","structure_material":"石造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0507","desc":"主屋西側に接続する釜屋形。コーガ石を用いた石造平屋建南北棟の片流屋根で鉄板葺とする。南を戸口とし、内部は一室の土間で西面に二箇所窓を開け、かつては北側に床を設けていた。妻壁上部の痕跡から、かつてヴォールト状屋根であったことがわかる釜屋形。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014762"},{"id":"00013049","register_sub_id":"101","register_pk":"368234","name":"旧赤羽台団地四一号棟","kana":"きゅうあかばねだいだんちよんじゅういちごうとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都北区赤羽台一丁目1-1","lat":35.77714444,"lng":139.71603333,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積374㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0422","desc":"団地内中央南寄りに建つ板状住棟。全住戸への採光、換気を考慮し、住戸は南北に面する。各戸の間取は、南面中央の台所両側に六畳と四畳半の居室を配す。平面形式は標準設計の61型を基に改良を加えたプランで、公団住宅の初期の様相を知る上で重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013049"},{"id":"00013051","register_sub_id":"101","register_pk":"368236","name":"旧赤羽台団地四三号棟","kana":"きゅうあかばねだいだんちよんじゅうさんごうとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都北区赤羽台一丁目1-1","lat":35.77664167,"lng":139.71631389,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積149㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0424","desc":"四二号棟の北に建つポイント型住棟。ポイント型住棟は昭和30年代を中心に建設されるが、建設費や土地利用効率において不利な面があり、昭和40年代には建設されなくなった。同型住棟の残存例は少なく、四二、四四号棟とともにまとまって残る例は希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013051"},{"id":"00013050","register_sub_id":"101","register_pk":"368235","name":"旧赤羽台団地四二号棟","kana":"きゅうあかばねだいだんちよんじゅうにごうとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都北区赤羽台一丁目1-1","lat":35.77633056,"lng":139.71655,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積149㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0423","desc":"団地内の中央南端に建つポイント型住棟。三角形平面の階段室の周囲に各階三住戸を放射状に配置し、Ｙ字形の平面形状とする。板状住棟が平行に配置される団地空間に変化を与えている。四三、四四号棟とともに団地内の特徴的な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013050"},{"id":"00013052","register_sub_id":"101","register_pk":"368237","name":"旧赤羽台団地四四号棟","kana":"きゅうあかばねだいだんちよんじゅうよんごうとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都北区赤羽台一丁目1-1","lat":35.77698889,"lng":139.71635556,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積149㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0425","desc":"四三号棟の北東に建つポイント型住棟。各住戸とも南側に設置するバルコニーに面して畳敷の居室を二室配す。北側には三室目の居室と浴室、便所、台所及び玄関を配置する。四二、四三号棟とともに団地南側の景観上のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013052"},{"id":"00014329","register_sub_id":"101","register_pk":"511318","name":"旧赤星鉄馬邸","kana":"きゅうあかぼしてつまてい","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都武蔵野市吉祥寺本町四丁目1823他","lat":35.70935,"lng":139.57200833,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積392㎡、扉付コンクリート塀延長12.3m付","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2022.10.31(令和4.10.31)","register_no":"13 - 0468","desc":"成蹊学園の南に広大な敷地を構えた実業家邸宅で、建築家レーモンド設計。中央で屈曲した東西に長い中廊下型平面で、前庭側外観は水平連続窓とする。キャノピーを差し出した玄関にはスリットを入れた曲面壁の階段室を構え、コンクリート造形の可能性を追求。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014329"},{"id":"00015294","register_sub_id":"101","register_pk":"532418","name":"旧飯田家住宅店舗兼主屋","kana":"きゅういいだけじゅうたくてんぽけんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中央区佃一丁目8","lat":35.66723056,"lng":139.78250278,"geo_status":"db","era":"大正9年頃／大正後期改修、昭和前期増築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、鉄板葺及び瓦葺、建築面積78㎡、防火水槽付","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0515","desc":"佃島の中通りに東面して建つ、旧魚問屋兼仲買を営んだ店舗兼主屋。２階建切妻造平入鉄板葺で軒は出桁造で外壁簓子下見板張。店舗は人研仕上の土間床に井戸と生簀を残し、奥と二階に数寄屋風の座敷を構える。震災と戦災を免れ漁師町の風情を伝える貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015294"},{"id":"00014328","register_sub_id":"101","register_pk":"511317","name":"旧板垣家住宅主屋","kana":"きゅういたがきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都足立区千住５丁目66","lat":35.75455833,"lng":139.80430833,"geo_status":"db","era":"昭和13年／平成17年・令和2年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"13 - 0467","desc":"千住宿の日光街道と水戸街道分岐に位置する洋館付二階建和風住宅。入母屋造桟瓦葺で下見板張壁、洋館は入母屋造の玄関西脇に設け、切妻造フランス瓦葺、台形出窓が瀟洒。中廊下平面で、各階に南面する床構え付座敷を配す。街道沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014328"},{"id":"00011269","register_sub_id":"101","register_pk":"209105","name":"旧大田黒家住宅蔵","kana":"きゅうおおたぐろけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区荻窪三丁目21他","lat":35.700919,"lng":139.624432,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0367","desc":"木造二階建の蔵。小屋はトラスで、外壁はモルタル塗とする。南面西寄りに扉口を開き、内外とも簡素にまとめるが、階段手摺には洋風意匠を見せ、外壁上部で土蔵風に鉢巻等を模る。窓部は鉄格子を嵌めて鉄扉とする。昭和戦前期の邸宅の様相を今に伝える蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011269"},{"id":"00011268","register_sub_id":"101","register_pk":"209104","name":"旧大田黒家住宅洋館","kana":"きゅうおおたぐろけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区荻窪三丁目20-1","lat":35.700504,"lng":139.624545,"geo_status":"db","era":"昭和8／昭和56改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0366","desc":"音楽評論家の大田黒元雄が住宅の離れとして建てたもので、切妻造桟瓦葺。一階ホールは床を寄木張、壁は銅色の濃淡をつけた碁盤縞の壁紙貼り、天井は漆喰塗とし、北面には書棚、西面には暖炉を備える。立ちの高い瀟洒な外観とともに、特色ある意匠を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011268"},{"id":"00015155","register_sub_id":"101","register_pk":"530579","name":"旧唐木田家住宅主屋","kana":"きゅうからきだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都台東区上野桜木一丁目19","lat":35.72125278,"lng":139.77202222,"geo_status":"db","era":"大正9年／昭和前期増築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"13 - 0513","desc":"上野桜木に位置する和風住宅。敷地北寄りに南面して建つ二階建寄棟造桟瓦葺で、西寄りに寄棟造玄関を付す。各階に続き座敷を配し、東・南に廻らす縁は、一階は濡縁、二階は高欄を付して庭を望む。ガラス窓を用いた開放的な外観で閑静な住宅地の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015155"},{"id":"00013237","register_sub_id":"101","register_pk":"366226","name":"旧川井家住宅土蔵","kana":"きゅうかわいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都多摩市鶴牧二丁目22-6","lat":35.61825556,"lng":139.415425,"geo_status":"db","era":"大正後期／昭和57年頃改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、金属板葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"13 － 0433","desc":"主屋の南東に建つ。土蔵造二階建、置屋根形式の切妻造金属板葺で、外壁はモルタル塗、腰を人造石研出仕上とする。北面に戸口を設け、下屋を付し、二階に窓を穿つ。内部は一、二階とも一室で壁は竪羽目板張とする。主屋や周囲の樹木とともに地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013237"},{"id":"00014572","register_sub_id":"101","register_pk":"515114","name":"旧川嶋屋米倉庫","kana":"きゅうかわしまやこめそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都台東区上野桜木二丁目36-3","lat":35.72164722,"lng":139.77123889,"geo_status":"db","era":"明治29年頃／昭和中期改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積24㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0487","desc":"上野桜木にある米屋店舗の背面に位置する旧米倉庫。切妻造桟瓦葺、軒出桁造、二階建の真壁造にトタン張とする。米屋廃業後まもなく住居に改修し、二階は押入付の和室で西面に刎高欄付の小さな露台を出す。路地の先にあり、下町の家並みを形成する付属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014572"},{"id":"00014571","register_sub_id":"101","register_pk":"515113","name":"旧川嶋屋店舗兼住居","kana":"きゅうかわしまやてんぽけんじゅうきょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都台東区上野桜木二丁目36-3","lat":35.72160556,"lng":139.77132222,"geo_status":"db","era":"明治29年頃／昭和中期改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0486","desc":"上野桜木にある米屋の店舗兼住居。南面する二戸の間に路地を通して一体で切妻造平入桟瓦葺、軒出桁造とした長屋風の真壁造町家。東側は元は店舗兼住居で、奥に庭と縁を巡らす座敷を配し、二階は従業員部屋、西側は貸家とした。寺町界隈の景観を形成して貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014571"},{"id":"00014754","register_sub_id":"101","register_pk":"519012","name":"旧川端龍子邸主屋及び中門","kana":"きゅうかわばたりゅうしていおもやおよびちゅうもん","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都大田区南馬込四丁目49-11","lat":35.58276944,"lng":139.71554722,"geo_status":"db","era":"昭和26年／昭和29年増築、平成15年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0499","desc":"南馬込の住宅地に位置する日本画家川端龍子の住宅。主屋は平屋建切妻造桟瓦葺の南北棟二棟を雁行して配し、東に切妻造桟瓦葺の中門を延ばす。外壁腰には竹の木賊張とし、主要室の内壁を大壁として、天井周囲まで塗廻すなど龍子の嗜好を反映した主屋及び中門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014754"},{"id":"00014757","register_sub_id":"101","register_pk":"519015","name":"旧川端龍子邸画室","kana":"きゅうかわばたりゅうしていがしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都大田区南馬込四丁目49-11","lat":35.58301667,"lng":139.71562222,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0502","desc":"敷地北西に位置する平屋建切妻造銅板葺の南北棟で、南西に土庇を付す。側柱は円柱とし、内部は一室の板敷で、折上天井には石膏ボードを斜め透かし張りの布張仕上とし、側廻りに大判ガラスの引戸を建てる。大作制作を主とした龍子らしい開放的で大空間の画室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014757"},{"id":"00014756","register_sub_id":"101","register_pk":"519014","name":"旧川端龍子邸持仏堂","kana":"きゅうかわばたりゅうしていじぶつどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都大田区南馬込四丁目49-11","lat":35.58272778,"lng":139.71528333,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"コンクリートブロック造平屋建、瓦葺、建築面積13㎡","structure_material":"コンクリートブロック造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0501","desc":"仏間棟の西に接続するコンクリートブロック造切妻造妻入桟瓦葺の東西棟。束で床版を持上げ、西妻は円柱上の梁に棟束を立て、螻羽を深くつくる。内部は一室で西を祭壇、上部は尖頭のヴォールト天井、北と南の各１箇所に尖頭アーチ窓を開け独創的意匠の持仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014756"},{"id":"00014755","register_sub_id":"101","register_pk":"519013","name":"旧川端龍子邸仏間棟","kana":"きゅうかわばたりゅうしていぶつまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都大田区南馬込四丁目49-11","lat":35.58271944,"lng":139.71540833,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積78㎡","structure_material":"木造平屋一部2階建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0500","desc":"主屋の西に接続する平屋一部二階建の桟瓦葺。全体に矩折れの平面で１階は仏間の北東に控えの間を配し、二階は１室の寝室。持仏の鑑賞室となる仏間は１７畳半の畳敷で、天井中央に長尺板を張る。側廻りに大判ガラスの引戸を多用した洗練されたつくりの仏間棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014755"},{"id":"00014330","register_sub_id":"101","register_pk":"511319","name":"旧佐橋家住宅主屋","kana":"きゅうさはしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都調布市西つつじケ丘一丁目27","lat":35.65864167,"lng":139.57164167,"geo_status":"db","era":"昭和11年／同37年移築・同６０年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"13 - 0469","desc":"甲州街道沿いに数寄者が自ら設計した茶室付の和風住宅。富士山を望んだ二階建で、切妻造桟瓦葺四方下屋、真壁造漆喰仕上とする。玄関から仏間、茶の間、寄付の三方に動線を分けて平面に工夫を凝らし、舟底天井茶室など、平面と空間構成に創意工夫がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014330"},{"id":"00014331","register_sub_id":"101","register_pk":"511320","name":"旧佐橋家住宅門","kana":"きゅうさはしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都調布市西つつじケ丘一丁目27-1","lat":35.65851111,"lng":139.57165,"geo_status":"db","era":"昭和11年／同37年移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、鉄板葺、間口2.0m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"13 - 0470","desc":"甲州街道に開く数寄者の住宅表門。切妻造金属板葺で元は竹で押さえた杉皮葺。軒裏は杉柾目板に葭を挟む。棟木と軒桁をナグリ仕上の柱で支え、欄間は曲がり枝の中備えに漆喰壁を載せる。引違板戸を建て、背後に主屋の茶室へ飛石を延ばす、侘びた外露地門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014331"},{"id":"00007194","register_sub_id":"101","register_pk":"108176","name":"旧滋賀家住宅主屋","kana":"きゅうしがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区下井草4-260-2","lat":35.72138048,"lng":139.61821469,"geo_status":"db","era":"昭和6年／平成10年移築改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"13 － 0235","desc":"角地に占める敷地の東寄りに東面して建つ木造平屋建。屋根は切妻造で、正面中央を葺き降ろし、フランス瓦葺とする。桁行に大きく３分し、中央に玄関ホールを配し、その前方に広いベランダ状のテラスを置く。土間にはアール・デコ風の装飾が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007194"},{"id":"00008659","register_sub_id":"101","register_pk":"149380","name":"旧島津家住宅アトリエ","kana":"きゅうしまづけじゅうたくあとりえ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都新宿区中井2-2096-18","lat":35.71657452,"lng":139.68484288,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積92㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0282","desc":"正面に大きな切妻破風を見せる木造平屋建。建築面積92㎡。桟瓦葺とし、壁モルタル仕上げで、妻上部は板張。北側には画室を大きく配し、北面は天井まで窓を開ける。南寄りに中2階を設け、1階はもとは吹き放された。目白文化村界隈の趣を伝えるアトリエ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008659"}];
